-- NEET UG previous-year questions (official NTA papers), 2021.
-- Question text is the exam's; answers are solved and cross-checked independently by UG Prep
-- (not the official key); one-liners and explanations are original. Idempotent by id.
INSERT INTO public.questions (id, exam, subject, topic, stem, options, correct_option_id, one_liner,
  explanation, distractors, high_yield, difficulty, is_pyq, pyq_year, repeat_count, source, image_url)
VALUES
('c33cd809-8869-57e2-aa76-6c52d27e9c87', 'neet_ug', 'Botany', 'Plant Kingdom', 'Which of the following algae produce Carrageen?', '[{"id": "a", "text": "Brown algae"}, {"id": "b", "text": "Red algae"}, {"id": "c", "text": "Blue-green algae"}, {"id": "d", "text": "Green algae"}]'::jsonb, 'b', 'Carrageen is a commercial hydrocolloid obtained from red algae (Rhodophyceae).', 'Algae yield commercially useful hydrocolloids: algin comes from brown algae, while carrageen and agar come from red algae. So carrageen points to Rhodophyceae.', '{"a": "Brown algae are the source of algin, not carrageen.", "c": "Blue-green algae (cyanobacteria) are not a source of hydrocolloids.", "d": "Green algae such as Chlorella are used as food supplements, not for carrageen."}'::jsonb, 'Algin comes from brown algae; agar and carrageen come from red algae.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('0564dba6-6ee6-5223-b9bf-331494bb32df', 'neet_ug', 'Botany', 'Plant Kingdom', 'Genera like Selaginella and Salvinia produce two kinds of spores. Such plants are known as:', '[{"id": "a", "text": "Heterosorus"}, {"id": "b", "text": "Homosporous"}, {"id": "c", "text": "Heterosporous"}, {"id": "d", "text": "Homosorus"}]'::jsonb, 'c', 'Plants that produce two kinds of spores (micro- and megaspores) are heterosporous.', 'Selaginella and Salvinia form small microspores and large megaspores, which give rise to male and female gametophytes respectively. This condition is called heterospory, and it is a precursor to the seed habit.', '{"a": "''Heterosorus'' is not a term used for spore type.", "b": "Homosporous plants make only one kind of spore, as in most ferns.", "d": "''Homosorus'' is not a recognised term."}'::jsonb, 'Heterospory in Selaginella and Salvinia is considered a precursor to the seed habit.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('66ddba86-8880-5c06-b5aa-a6eacd93576b', 'neet_ug', 'Botany', 'Plant Kingdom', 'Which of the following algae contains mannitol as reserve food material?', '[{"id": "a", "text": "Gracilaria"}, {"id": "b", "text": "Volvox"}, {"id": "c", "text": "Ulothrix"}, {"id": "d", "text": "Ectocarpus"}]'::jsonb, 'd', 'Brown algae such as Ectocarpus store laminarin and mannitol.', 'Reserve food differs by algal class: green algae store starch, red algae store floridean starch, and brown algae (Phaeophyceae) store laminarin or mannitol. Ectocarpus is a brown alga.', '{"a": "Gracilaria is a red alga that stores floridean starch.", "b": "Volvox is a green alga that stores starch.", "c": "Ulothrix is a green alga that stores starch."}'::jsonb, 'Phaeophyceae store laminarin or mannitol; Rhodophyceae store floridean starch.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('180dac95-764f-5c04-a79f-4019e37163b2', 'neet_ug', 'Botany', 'Plant Kingdom', 'Gemmae are present in:', '[{"id": "a", "text": "Pteridophytes"}, {"id": "b", "text": "Some Gymnosperms"}, {"id": "c", "text": "Some Liverworts"}, {"id": "d", "text": "Mosses"}]'::jsonb, 'c', 'Gemmae are asexual buds formed in gemma cups on the thallus of some liverworts such as Marchantia.', 'Liverworts reproduce asexually by fragmentation or by gemmae. Gemmae are green, multicellular buds that develop in small cups on the thallus, detach, and grow into new individuals.', '{"a": "Pteridophytes reproduce mainly by spores; gemmae are not typical of them.", "b": "Gymnosperms do not form gemmae.", "d": "Mosses spread vegetatively mainly by fragmentation and budding of the secondary protonema."}'::jsonb, 'Gemma cups on the Marchantia thallus bear gemmae used for asexual reproduction.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('8b97abec-5241-5960-bb25-77b99f945539', 'neet_ug', 'Botany', 'Morphology of Flowering Plants', 'Diadelphous stamens are found in:', '[{"id": "a", "text": "Citrus"}, {"id": "b", "text": "Pea"}, {"id": "c", "text": "China rose and citrus"}, {"id": "d", "text": "China rose"}]'::jsonb, 'b', 'Pea (Fabaceae) has diadelphous stamens, arranged as (9)+1.', 'When stamens are fused into two bundles the condition is diadelphous. In pea, nine filaments are united and one is free. China rose is monadelphous and citrus is polyadelphous.', '{"a": "Citrus has polyadelphous stamens (more than two bundles).", "c": "China rose is monadelphous and citrus is polyadelphous; neither is diadelphous.", "d": "China rose has monadelphous stamens (one bundle)."}'::jsonb, 'Monadelphous: China rose; diadelphous: pea; polyadelphous: citrus.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('80d221b6-eefa-5ca7-88ce-3eb89c67f2d1', 'neet_ug', 'Botany', 'Anatomy of Flowering Plants', 'Match List-1 with List-2
List-1 | List-2
(A) Lenticels | (i) Phellogen
(B) Cork cambium | (ii) Suberin deposition
(C) Secondary cortex | (iii) Exchange of gases
(D) Cork | (iv) Phelloderm
Choose the correct answer from the options given below.', '[{"id": "a", "text": "A-iii B-i C-iv D-ii"}, {"id": "b", "text": "A-ii B-iii C-iv D-i"}, {"id": "c", "text": "A-iv B-ii C-i D-iii"}, {"id": "d", "text": "A-iv B-i C-iii D-ii"}]'::jsonb, 'a', 'Lenticels allow exchange of gases, cork cambium is phellogen, secondary cortex is phelloderm, and cork cells are suberised.', 'Phellogen (cork cambium) cuts off cork (phellem) towards the outside, and its walls become suberised. It cuts off secondary cortex (phelloderm) towards the inside. Lenticels are lens-shaped openings in the bark that permit gas exchange.', '{"b": "Lenticels are not sites of suberin deposition; they allow gas exchange.", "c": "Lenticels are not phelloderm, and cork is not phellogen.", "d": "Secondary cortex is phelloderm, not a site of gas exchange."}'::jsonb, 'Periderm = phellem + phellogen + phelloderm.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('bc47fe39-b18e-5aa8-b45e-217a696ceab9', 'neet_ug', 'Botany', 'Anatomy of Flowering Plants', 'Match List-1 with List-2
List-1 | List-2
(A) Cells with active cell division capacity | (i) Vascular tissues
(B) Tissue having all cells similar in structure and function | (ii) Meristematic tissue
(C) Tissue having different types of cells | (iii) Sclereids
(D) Dead cells with highly thickened walls and narrow lumen | (iv) Simple tissue
Select the correct answer from the options given below.', '[{"id": "a", "text": "A-iv B-iii C-ii D-i"}, {"id": "b", "text": "A-i B-ii C-iii D-iv"}, {"id": "c", "text": "A-iii B-ii C-iv D-i"}, {"id": "d", "text": "A-ii B-iv C-i D-iii"}]'::jsonb, 'd', 'Dividing cells form meristem, uniform cells form simple tissue, mixed cell types form complex (vascular) tissue, and sclereids are dead and thick-walled.', 'Meristematic tissue keeps the ability to divide. Simple tissues such as parenchyma are made of one cell type. Complex tissues such as xylem and phloem contain several cell types. Sclereids are dead sclerenchyma cells with heavily lignified walls and a very narrow lumen.', '{"a": "This mismatches every pair, for example it calls meristem a simple tissue.", "b": "Vascular tissue is complex, not the meristem.", "c": "Sclereids are not actively dividing cells."}'::jsonb, 'Xylem and phloem are complex tissues; parenchyma, collenchyma and sclerenchyma are simple tissues.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('8c032edf-2967-5c4e-b0db-dce83b0913ef', 'neet_ug', 'Botany', 'Cell: The Unit of Life', 'Which of the following is an incorrect statement?', '[{"id": "a", "text": "Microbodies are present both in plant and animal cells."}, {"id": "b", "text": "The perinuclear space forms a barrier between the materials present inside the nucleus and that of the cytoplasm."}, {"id": "c", "text": "Nuclear pores act as passages for proteins and RNA molecules in both directions between nucleus and cytoplasm."}, {"id": "d", "text": "Mature sieve tube elements possess a conspicuous nucleus and usual cytoplasmic organelles."}]'::jsonb, 'd', 'Mature sieve tube elements lack a nucleus.', 'Sieve tube elements are living, but at maturity they lose their nucleus and most organelles, and they depend on companion cells. NCERT cites them as an example of eukaryotic cells without a nucleus. The other three statements are correct NCERT facts about microbodies and the nuclear envelope.', '{"a": "This is true; microbodies occur in both plant and animal cells.", "b": "This is true; the perinuclear space between the two nuclear membranes acts as a barrier.", "c": "This is true; nuclear pores allow two-way movement of RNA and proteins."}'::jsonb, 'Mature mammalian RBCs and plant sieve tube cells lack a nucleus.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('abfa5a18-2742-5db8-8bbb-1f3ed31a97aa', 'neet_ug', 'Botany', 'Cell: The Unit of Life', 'Match List-1 with List-2
List-1 | List-2
(A) Cristae | (i) Primary constriction in chromosome
(B) Thylakoids | (ii) Disc-shaped sacs in Golgi apparatus
(C) Centromere | (iii) Infoldings in mitochondria
(D) Cisternae | (iv) Flattened membranous sacs in stroma of plastids
Choose the correct answer from the options given below.', '[{"id": "a", "text": "A-i B-iv C-iii D-ii"}, {"id": "b", "text": "A-iii B-iv C-i D-ii"}, {"id": "c", "text": "A-ii B-iii C-iv D-i"}, {"id": "d", "text": "A-iv B-iii C-ii D-i"}]'::jsonb, 'b', 'Cristae are mitochondrial infoldings, thylakoids are stromal sacs, the centromere is the primary constriction, and cisternae are Golgi discs.', 'The inner mitochondrial membrane folds into cristae. Chloroplast stroma contains flattened thylakoid sacs. The centromere forms the primary constriction of a chromosome, and the Golgi apparatus is made of stacked, disc-shaped cisternae.', '{"a": "Cristae are not a chromosomal constriction.", "c": "Thylakoids are not mitochondrial infoldings.", "d": "Centromere is not a Golgi structure."}'::jsonb, 'Golgi cisternae have a cis (forming) face and a trans (maturing) face.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('6dacf1a5-e1d0-5cd6-80d9-3782429217a4', 'neet_ug', 'Botany', 'Cell: The Unit of Life', 'When the centromere is situated in the middle of two equal arms of chromosomes, the chromosome is referred as:', '[{"id": "a", "text": "Telocentric"}, {"id": "b", "text": "Sub-metacentric"}, {"id": "c", "text": "Acrocentric"}, {"id": "d", "text": "Metacentric"}]'::jsonb, 'd', 'A median centromere with two equal arms makes a chromosome metacentric.', 'Chromosomes are classified by centromere position: median gives metacentric, slightly away from the middle gives sub-metacentric, near one end gives acrocentric, and terminal gives telocentric.', '{"a": "A telocentric chromosome has a terminal centromere.", "b": "A sub-metacentric chromosome has arms of unequal length.", "c": "An acrocentric chromosome has its centromere close to one end."}'::jsonb, 'Centromere position decides whether a chromosome is metacentric, sub-metacentric, acrocentric or telocentric.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('e810af71-4b91-5c68-8c5e-8f6284f9310b', 'neet_ug', 'Botany', 'Biomolecules', 'Which of the following are not secondary metabolites in plants?', '[{"id": "a", "text": "Amino acids, glucose"}, {"id": "b", "text": "Vinblastin, curcumin"}, {"id": "c", "text": "Rubber, gums"}, {"id": "d", "text": "Morphine, codeine"}]'::jsonb, 'a', 'Amino acids and glucose are primary metabolites.', 'Primary metabolites such as sugars, amino acids and nucleotides have known roles in normal physiology. Secondary metabolites include alkaloids (morphine, codeine), drugs (vinblastin, curcumin), and polymers such as rubber and gums.', '{"b": "Vinblastin and curcumin are secondary metabolites used as drugs.", "c": "Rubber and gums are polymeric secondary metabolites.", "d": "Morphine and codeine are alkaloids, which are secondary metabolites."}'::jsonb, 'Secondary metabolites include alkaloids, terpenoids, essential oils, toxins, lectins, drugs and pigments.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('3fca0f93-c7a6-5299-b489-3f0a19ccace1', 'neet_ug', 'Botany', 'Cell Cycle and Cell Division', 'Which of the following stages of meiosis involves division of centromere?', '[{"id": "a", "text": "Metaphase II"}, {"id": "b", "text": "Anaphase II"}, {"id": "c", "text": "Telophase II"}, {"id": "d", "text": "Metaphase I"}]'::jsonb, 'b', 'Centromeres split at anaphase II, which separates the sister chromatids.', 'In anaphase I homologous chromosomes separate and the centromeres stay intact. In anaphase II the centromere of each chromosome splits, so the sister chromatids move to opposite poles.', '{"a": "In metaphase II chromosomes only align at the equator.", "c": "In telophase II the nuclear envelope re-forms after the chromatids have separated.", "d": "In metaphase I bivalents align and the centromeres do not divide."}'::jsonb, 'Centromeres split in mitotic anaphase and in anaphase II, but not in anaphase I.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('024a16c1-2e6e-5e31-bcb0-4014ff41ac31', 'neet_ug', 'Botany', 'Photosynthesis in Higher Plants', 'The first stable product of CO₂ fixation in sorghum is:', '[{"id": "a", "text": "Oxaloacetic acid"}, {"id": "b", "text": "Succinic acid"}, {"id": "c", "text": "Phosphoglyceric acid"}, {"id": "d", "text": "Pyruvic acid"}]'::jsonb, 'a', 'Sorghum is a C₄ plant, and its first stable product is the 4-carbon oxaloacetic acid.', 'In C₄ plants, PEP carboxylase in mesophyll cells fixes CO₂ onto phosphoenolpyruvate, forming oxaloacetic acid (OAA). Sorghum, maize and sugarcane are C₄ plants. 3-PGA is the first product only in C₃ plants.', '{"b": "Succinic acid is an intermediate of the Krebs cycle.", "c": "PGA is the first stable product in C₃ plants.", "d": "Pyruvate is regenerated in the bundle sheath and is not the first stable product."}'::jsonb, 'C₄ plants show Kranz anatomy, and PEPcase is their primary CO₂ acceptor enzyme.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('f60be617-60bf-55e3-b5d5-27d6351cd9fa', 'neet_ug', 'Botany', 'Plant Growth and Development', 'The site of perception of light in plants during photoperiodism is:', '[{"id": "a", "text": "Stem"}, {"id": "b", "text": "Axillary bud"}, {"id": "c", "text": "Leaf"}, {"id": "d", "text": "Shoot apex"}]'::jsonb, 'c', 'Leaves perceive the photoperiod, and the flowering stimulus then moves to the shoot apices.', 'NCERT explains that shoot apices change into floral apices, but the light or dark period is perceived by the leaves. A hormonal stimulus is thought to travel from the leaves to the apex.', '{"a": "The stem is not the site of photoperiodic perception.", "b": "Axillary buds respond to the stimulus but do not perceive the photoperiod.", "d": "The shoot apex is where flowering happens, not where light is sensed."}'::jsonb, 'Leaves sense photoperiod; the floral stimulus is called florigen.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('467a6ca9-2115-54c2-89b3-2c3441ac535e', 'neet_ug', 'Botany', 'Plant Growth and Development', 'The plant hormone used to destroy weeds in a field is:', '[{"id": "a", "text": "NAA"}, {"id": "b", "text": "2, 4-D"}, {"id": "c", "text": "IBA"}, {"id": "d", "text": "IAA"}]'::jsonb, 'b', '2,4-D is a synthetic auxin used as a herbicide against dicot weeds.', '2,4-D (2,4-dichlorophenoxyacetic acid) kills broad-leaved dicot weeds but does not affect mature monocots, which is why it is used in cereal fields and lawns. NAA and IBA are used for rooting, and IAA is a natural auxin.', '{"a": "NAA is used for rooting and to prevent fruit drop.", "c": "IBA is mainly used to induce roots in cuttings.", "d": "IAA is the natural auxin and is not used as a weedicide."}'::jsonb, '2,4-D is a selective weedicide that kills dicots and spares monocots.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('a2772246-04e6-5107-a1d0-c3c959c8dd0f', 'neet_ug', 'Botany', 'Plant Growth and Development', 'Plants follow different pathways in response to environment or phase of life to form different kinds of structures. This ability is called:', '[{"id": "a", "text": "Flexibility"}, {"id": "b", "text": "Plasticity"}, {"id": "c", "text": "Maturity"}, {"id": "d", "text": "Elasticity"}]'::jsonb, 'b', 'Plasticity is the ability to follow different developmental pathways and form different structures.', 'NCERT defines plasticity as the capacity of plants to produce different structures in response to environment or life phase. Heterophylly in cotton, coriander and larkspur (by life phase) and in buttercup (by environment) are examples.', '{"a": "''Flexibility'' is not the NCERT term for this ability.", "c": "Maturity is a developmental stage, not an ability.", "d": "Elasticity is a physical property of cell walls."}'::jsonb, 'Heterophylly in buttercup and larkspur is an example of plasticity.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('29227bf6-8dc4-55ae-890c-b0720bcf4c17', 'neet_ug', 'Botany', 'Sexual Reproduction in Flowering Plants', 'A typical angiosperm embryo sac at maturity is:', '[{"id": "a", "text": "7- nucleate and 8-celled"}, {"id": "b", "text": "7- nucleate and 7-celled"}, {"id": "c", "text": "8- nucleate and 8- celled"}, {"id": "d", "text": "8-nucleate and 7- celled"}]'::jsonb, 'd', 'The mature embryo sac has 8 nuclei in 7 cells, because the central cell holds two polar nuclei.', 'Three mitotic divisions of the functional megaspore produce 8 nuclei. These form 3 antipodals, 2 synergids, 1 egg cell, and 1 large central cell containing 2 polar nuclei. That makes 7 cells and 8 nuclei.', '{"a": "There are 8 nuclei, not 7, and only 7 cells.", "b": "There are 8 nuclei, not 7.", "c": "The two polar nuclei share one central cell, so there are only 7 cells."}'::jsonb, 'Polygonum-type embryo sac: 8-nucleate, 7-celled.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('f306660e-5d17-5c92-81ab-583a172e0ddb', 'neet_ug', 'Botany', 'Sexual Reproduction in Flowering Plants', 'The term used for transfer of pollen grains from anthers of one plant to stigma of different plant which, during pollination, brings genetically different types of pollen grains to stigma, is:', '[{"id": "a", "text": "Geitonogamy"}, {"id": "b", "text": "Chasmogamy"}, {"id": "c", "text": "Cleistogamy"}, {"id": "d", "text": "Xenogamy"}]'::jsonb, 'd', 'Xenogamy is the transfer of pollen to the stigma of a different plant.', 'Xenogamy is the only type of pollination that brings genetically different pollen to the stigma. Geitonogamy transfers pollen between flowers of the same plant, so it is genetically the same as autogamy.', '{"a": "Geitonogamy occurs between flowers of the same plant.", "b": "Chasmogamous flowers have exposed anthers and stigma; the term does not mean pollen transfer between plants.", "c": "Cleistogamous flowers never open and are strictly self-pollinated."}'::jsonb, 'Only xenogamy brings genetically different pollen to the stigma.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('14aa47e2-6b7c-5c6f-8e46-07b28c1c024a', 'neet_ug', 'Botany', 'Principles of Inheritance and Variation', 'The production for gametes by the parents, formation of zygotes, the F₁ and F₂ plants, can be understood from a diagram called:', '[{"id": "a", "text": "Punch square"}, {"id": "b", "text": "Punnett square"}, {"id": "c", "text": "Net square"}, {"id": "d", "text": "Bullet square"}]'::jsonb, 'b', 'A Punnett square shows the gametes, the zygotes and the F₁/F₂ genotypes.', 'Reginald C. Punnett devised a checkerboard that places the gametes of each parent on the two axes. The cells of the grid then show all possible zygote combinations and their ratios.', '{"a": "''Punch square'' is not a genetic term.", "c": "''Net square'' is not a genetic term.", "d": "''Bullet square'' is not a genetic term."}'::jsonb, 'The Punnett square was developed by the British geneticist Reginald C. Punnett.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('36f8323b-1615-5c05-a69d-a871f0c8eb79', 'neet_ug', 'Botany', 'Molecular Basis of Inheritance', 'Complete the flow chart on central dogma.
(A) ↻ DNA —(B)→ mRNA —(C)→ (D)', '[{"id": "a", "text": "(A)-Translation; (B)-Replication; (C)-Transcription; (D)-Transduction"}, {"id": "b", "text": "(A)-Replication; (B)-Transcription; (C)-Translation; (D)-Protein"}, {"id": "c", "text": "(A)-Transduction; (B)-Translation; (C)-Replication; (D)-Protein"}, {"id": "d", "text": "(A)-Replication; (B)-Transcription; (C)-Transduction; (D)-Protein"}]'::jsonb, 'b', 'DNA replicates itself, is transcribed to mRNA, and mRNA is translated into protein.', 'The loop on DNA represents replication (A). DNA to mRNA is transcription (B), and mRNA to protein is translation (C), so the product (D) is protein.', '{"a": "DNA copying itself is replication, not translation.", "c": "DNA to mRNA is transcription, not translation.", "d": "mRNA to protein is translation; transduction is a different process."}'::jsonb, 'Central dogma: DNA → RNA → protein (Crick).', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('6da5a77c-25f3-5bc4-9492-07e7136447ab', 'neet_ug', 'Zoology', 'Evolution', 'The factor that leads to Founder effect in a population is:', '[{"id": "a", "text": "Genetic recombination"}, {"id": "b", "text": "Mutation"}, {"id": "c", "text": "Genetic drift"}, {"id": "d", "text": "Natural selection"}]'::jsonb, 'c', 'The founder effect is a form of genetic drift.', 'When a small group separates and founds a new population, its allele frequencies can differ from the original by chance alone. This random change is genetic drift, and the founders may become a new species.', '{"a": "Recombination reshuffles alleles but does not cause the founder effect.", "b": "Mutation creates new alleles, which is not what causes the founder effect.", "d": "Natural selection is non-random, whereas the founder effect is a chance event."}'::jsonb, 'Gene flow, genetic drift, mutation, recombination and natural selection disturb Hardy-Weinberg equilibrium.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('ef46afef-08aa-5d69-9fc3-d777066d8a16', 'neet_ug', 'Zoology', 'Biotechnology: Principles and Processes', 'During the purification process for recombinant DNA technology, addition of chilled ethanol precipitates out:', '[{"id": "a", "text": "DNA"}, {"id": "b", "text": "Histones"}, {"id": "c", "text": "Polysaccharides"}, {"id": "d", "text": "RNA"}]'::jsonb, 'a', 'Chilled ethanol precipitates purified DNA as fine threads.', 'During DNA isolation, cells are lysed and treated with ribonuclease, protease and cellulase to remove RNA, proteins and polysaccharides. Adding chilled ethanol then makes the purified DNA precipitate out, and it can be spooled.', '{"b": "Histones are removed with protease.", "c": "Polysaccharides are removed with enzymes such as cellulase or chitinase.", "d": "RNA is removed with ribonuclease."}'::jsonb, 'DNA precipitated by chilled ethanol appears as fine threads that can be spooled.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('a0dd82e3-1563-50f7-965d-186063bcfaa3', 'neet_ug', 'Zoology', 'Biotechnology: Principles and Processes', 'DNA strands on a gel stained with ethidium bromide when viewed under UV radiation, appear as:', '[{"id": "a", "text": "Bright orange bands"}, {"id": "b", "text": "Dark red bands"}, {"id": "c", "text": "Bright blue bands"}, {"id": "d", "text": "Yellow bands"}]'::jsonb, 'a', 'DNA stained with ethidium bromide fluoresces as bright orange bands under UV light.', 'After agarose gel electrophoresis, the gel is stained with ethidium bromide, which intercalates into DNA. Under UV light the DNA fragments show up as bright orange bands, which can be cut out (elution).', '{"b": "EtBr-stained DNA does not show dark red bands.", "c": "EtBr-stained DNA does not fluoresce blue.", "d": "EtBr-stained DNA does not show yellow bands."}'::jsonb, 'DNA moves towards the anode in agarose gel; smaller fragments travel farther.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('43cb1270-7102-5481-ba4b-59b5f6ea5f0f', 'neet_ug', 'Zoology', 'Biotechnology and its Applications', 'When gene targetting involving gene amplification is attempted in an individual''s tissue to treat disease, it is known as:', '[{"id": "a", "text": "Gene therapy"}, {"id": "b", "text": "Molecular diagnosis"}, {"id": "c", "text": "Safety testing"}, {"id": "d", "text": "Biopiracy"}]'::jsonb, 'a', 'Correcting a disease by introducing genes into a person''s cells is gene therapy.', 'Gene therapy delivers a functional gene into a patient''s cells or tissue to correct a hereditary defect. The first clinical use was for ADA deficiency in 1990.', '{"b": "Molecular diagnosis detects disease, using methods such as PCR and ELISA; it does not treat it.", "c": "Safety testing assesses products and is not a treatment.", "d": "Biopiracy is the unauthorised use of bio-resources."}'::jsonb, 'The first gene therapy was given in 1990 to a 4-year-old girl with ADA deficiency.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('c4d51e4b-a01f-5529-be39-4218c89558e0', 'neet_ug', 'Zoology', 'Biotechnology and its Applications', 'Which of the following is not an application of PCR (Polymerase Chain Reaction)?', '[{"id": "a", "text": "Gene amplification"}, {"id": "b", "text": "Purification of isolated protein"}, {"id": "c", "text": "Detection of gene mutation"}, {"id": "d", "text": "Molecular diagnosis"}]'::jsonb, 'b', 'PCR amplifies DNA; it cannot purify proteins.', 'PCR copies a target DNA sequence many times. It is used for amplification, for detecting mutations and pathogens such as HIV early, and for molecular diagnosis. Protein purification relies on other methods such as chromatography.', '{"a": "Gene amplification is the main purpose of PCR.", "c": "PCR is used to detect mutations in suspected cancer patients.", "d": "PCR is a key tool in molecular diagnosis."}'::jsonb, 'PCR can detect very low amounts of pathogen DNA before symptoms appear.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('12dbba2b-e972-5e97-9ceb-d5f1a0d649fa', 'neet_ug', 'Zoology', 'Biotechnology: Principles and Processes', 'Which of the following is a correct sequence of steps in a PCR (Polymerase Chain Reaction)?', '[{"id": "a", "text": "Denaturation, Extension, Annealing"}, {"id": "b", "text": "Extension, Denaturation, Annealing"}, {"id": "c", "text": "Annealing, Denaturation, Extension"}, {"id": "d", "text": "Denaturation, Annealing, Extension"}]'::jsonb, 'd', 'Each PCR cycle runs denaturation, then annealing, then extension.', 'First, heat separates the DNA strands (denaturation). Next, primers bind to the single strands (annealing). Finally, thermostable Taq polymerase extends the primers (extension). The cycle is then repeated.', '{"a": "Primers must anneal before extension can occur.", "b": "Extension cannot happen before denaturation and annealing.", "c": "Primers cannot anneal before the strands are separated."}'::jsonb, 'Taq polymerase from Thermus aquaticus is used in PCR because it is heat-stable.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('a58f5ec9-1688-511e-bca3-03cfd8315650', 'neet_ug', 'Botany', 'Organisms and Populations', 'Inspite of interspecific competition in nature, which mechanism the competing species might have evolved for their survival?', '[{"id": "a", "text": "Competitive release"}, {"id": "b", "text": "Mutualism"}, {"id": "c", "text": "Predation"}, {"id": "d", "text": "Resource Partitioning"}]'::jsonb, 'd', 'Competing species coexist through resource partitioning.', 'Species that compete for the same resource can avoid exclusion by using it at different times or in different ways, which is resource partitioning. MacArthur showed this in five warbler species that forage in different parts of the same tree.', '{"a": "Competitive release is the expansion of a species'' range when its competitor is removed.", "b": "Mutualism benefits both species and is not a response to competition.", "c": "Predation is a separate interaction, not a coexistence mechanism."}'::jsonb, 'MacArthur''s warblers are the classic example of resource partitioning.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('7df1d8e3-e363-51f3-9f59-8869744e8a8c', 'neet_ug', 'Botany', 'Organisms and Populations', 'Amensalism can be represented as:', '[{"id": "a", "text": "Species A (+) ; Species B (+)"}, {"id": "b", "text": "Species A (-) ; Species B (-)"}, {"id": "c", "text": "Species A (+) ; Species B (0)"}, {"id": "d", "text": "Species A (-) : Species B (0)"}]'::jsonb, 'd', 'In amensalism one species is harmed (−) and the other is unaffected (0).', 'Population interactions are coded by their effects: mutualism is +/+, competition is −/−, commensalism is +/0, and amensalism is −/0.', '{"a": "+/+ represents mutualism.", "b": "−/− represents competition.", "c": "+/0 represents commensalism."}'::jsonb, 'Amensalism is −/0, and commensalism is +/0.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('6b508967-8c73-5d53-b249-7d65f754c1ea', 'neet_ug', 'Botany', 'Ecosystem', 'The amount of nutrients, such as carbon, nitrogen, phosphorus and calcium present in the soil at any given time is referred as:', '[{"id": "a", "text": "Climax community"}, {"id": "b", "text": "Standing state"}, {"id": "c", "text": "Standing crop"}, {"id": "d", "text": "Climax"}]'::jsonb, 'b', 'The amount of nutrients present in the soil at a given time is the standing state.', 'NCERT defines standing state as the amount of nutrients such as C, N, P and Ca in the soil at a given time. Standing crop refers instead to the living biomass present in each trophic level.', '{"a": "A climax community is the final stage of succession.", "c": "Standing crop is the living biomass in each trophic level.", "d": "Climax is the end point of succession."}'::jsonb, 'Standing state refers to nutrients; standing crop refers to biomass.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('95a02bd2-434c-5196-ac7c-a738b23229cb', 'neet_ug', 'Botany', 'Ecosystem', 'Which of the following statements is not correct?', '[{"id": "a", "text": "Pyramid of biomass in sea is generally upright."}, {"id": "b", "text": "Pyramid of energy is always upright."}, {"id": "c", "text": "Pyramid of numbers in a grassland ecosystem is upright."}, {"id": "d", "text": "Pyramid of biomass in sea is generally inverted."}]'::jsonb, 'a', 'The pyramid of biomass in the sea is inverted, not upright.', 'In the sea, the biomass of fish is greater than that of the phytoplankton supporting them, so the biomass pyramid is inverted. The energy pyramid is always upright, and the number pyramid of a grassland is upright.', '{"b": "This is true; energy decreases at each trophic level.", "c": "This is true; producers in a grassland outnumber the consumers.", "d": "This is true; marine biomass pyramids are generally inverted."}'::jsonb, 'The pyramid of energy can never be inverted.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('97a56f1f-9982-5c3a-9d85-97b6efb173d5', 'neet_ug', 'Botany', 'Ecosystem', 'In the equation GPP - R = NPP.
R represents:', '[{"id": "a", "text": "Retaradation factor"}, {"id": "b", "text": "Environment factor"}, {"id": "c", "text": "Respiration losses"}, {"id": "d", "text": "Radiant energy"}]'::jsonb, 'c', 'R is the energy that producers lose in respiration.', 'Gross primary productivity minus the energy used in respiration gives net primary productivity, which is the biomass available to heterotrophs.', '{"a": "A retardation factor is not part of the productivity equation.", "b": "R does not stand for an environmental factor.", "d": "Radiant energy is the input for GPP, not the subtracted term."}'::jsonb, 'NPP is the biomass available to consumers.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('bdeb809c-d2e9-5dbc-955e-73a52be041c4', 'neet_ug', 'Botany', 'Biological Classification', 'Which of the following statements is correct?', '[{"id": "a", "text": "Fusion of protoplasms between two motile or non-motile gametes is called plasmogamy."}, {"id": "b", "text": "Organisms that depend on living plants are called saprophytes."}, {"id": "c", "text": "Some of the organisms can fix atmospheric nitrogen in specialized cells called sheath cells."}, {"id": "d", "text": "Fusion of two cells is called Karyogamy."}]'::jsonb, 'a', 'Plasmogamy is the fusion of the protoplasms of two gametes.', 'In fungal sexual reproduction, plasmogamy (fusion of protoplasm) is followed by karyogamy (fusion of nuclei). Organisms living on living hosts are parasites, and cyanobacteria fix nitrogen in heterocysts.', '{"b": "Organisms that depend on living plants are parasites; saprophytes feed on dead matter.", "c": "Nitrogen-fixing cells are heterocysts, not sheath cells.", "d": "Karyogamy is the fusion of two nuclei, not of two cells."}'::jsonb, 'Fungal sexual cycle: plasmogamy, then karyogamy, then meiosis.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('6d5ad9e5-91d6-57ec-8617-f7a5d10dd2ef', 'neet_ug', 'Botany', 'Anatomy of Flowering Plants', 'Select the correct pair.
(a) In dicot leaves, vascular bundles are surrounded by large thick-walled cells - Conjunctive tissue
(b) Cells of medullary rays that form part of cambial rings - Interfascicular cambium
(c) Loose parenchyma cells rupturing the epidermis and forming a lens-shaped opening in bark - Spongy parenchyma
(d) Large colorless empty cells in the epidermis of grass leaves - Subsidiary cells', '[{"id": "a", "text": "In dicot leaves, vascular bundles are surrounded by large thick-walled cells - Conjunctive tissue"}, {"id": "b", "text": "Cells of medullary rays that form part of cambial rings - Interfascicular cambium"}, {"id": "c", "text": "Loose parenchyma cells rupturing the epidermis and forming a lens-shaped opening in bark - Spongy parenchyma"}, {"id": "d", "text": "Large colorless empty cells in the epidermis of grass leaves - Subsidiary cells"}]'::jsonb, 'b', 'Medullary ray cells next to the intrafascicular cambium become meristematic and form interfascicular cambium.', 'In dicot stems, the medullary ray cells between vascular bundles dedifferentiate into interfascicular cambium, which joins the intrafascicular strips to complete the cambial ring. The other pairs should read bundle sheath cells, lenticels (complementary cells) and bulliform cells respectively.', '{"a": "Thick-walled cells around the vascular bundles of leaves form the bundle sheath.", "c": "Loose cells that rupture the epidermis form lenticels (complementary cells), not spongy parenchyma.", "d": "Large colourless epidermal cells in grass leaves are bulliform cells."}'::jsonb, 'Bulliform cells help grass leaves roll up to reduce water loss.', 'med', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('dc672f13-974f-5221-86df-870e9e6afe5f', 'neet_ug', 'Botany', 'Biomolecules', 'Match List-1 with List-2
List-1 | List-2
(A) Protein | (i) C = C double bonds
(B) Unsaturated fatty acid | (ii) Phosphodiester bonds
(C) Nucleic acid | (iii) Glycosidic bonds
(D) Polysaccharide | (iv) Peptide bonds
Choose the correct answer from the options given below.', '[{"id": "a", "text": "A-i B-iv C-iii D-ii"}, {"id": "b", "text": "A-ii B-i C-iv D-iii"}, {"id": "c", "text": "A-iv B-iii C-i D-ii"}, {"id": "d", "text": "A-iv B-i C-ii D-iii"}]'::jsonb, 'd', 'Proteins have peptide bonds, unsaturated fats have C=C, nucleic acids have phosphodiester bonds, and polysaccharides have glycosidic bonds.', 'Amino acids are joined by peptide bonds. Unsaturated fatty acids contain one or more C=C double bonds. Nucleotides are linked by 3''-5'' phosphodiester bonds, and monosaccharides are linked by glycosidic bonds.', '{"a": "Proteins do not contain C=C as their linkage.", "b": "Proteins are not linked by phosphodiester bonds.", "c": "Unsaturated fatty acids are not defined by glycosidic bonds."}'::jsonb, 'Peptide bonds link proteins, glycosidic bonds link carbohydrates, and phosphodiester bonds link nucleic acids.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('70ab7913-c050-50d4-b122-6b51d63b0e99', 'neet_ug', 'Botany', 'Cell Cycle and Cell Division', 'Match List-1 with List-2
List-1 | List-2
(A) S phase | (i) Proteins are synthesized
(B) G₂ phase | (ii) Inactive phase
(C) Quiescent stage | (iii) Interval between mitosis and initiation of DNA replication
(D) G₁ phase | (iv) DNA replication
Choose the correct answer from the options given below.', '[{"id": "a", "text": "A-iv B-ii C-iii D-i"}, {"id": "b", "text": "A-iv B-i C-ii D-iii"}, {"id": "c", "text": "A-ii B-iv C-iii D-i"}, {"id": "d", "text": "A-iii B-ii C-i D-iv"}]'::jsonb, 'b', 'S phase replicates DNA, G₂ makes proteins, G₀ is inactive, and G₁ is the gap between mitosis and DNA replication.', 'DNA is replicated in S phase. G₂ prepares for mitosis through protein synthesis. Quiescent (G₀) cells stay metabolically active but do not proliferate. G₁ is the interval between mitosis and the start of DNA replication.', '{"a": "G₂ is not the inactive phase, and G₁ is not mainly the protein-synthesis gap before mitosis.", "c": "S phase is the phase of DNA replication.", "d": "S phase is DNA replication, not the G₁ interval."}'::jsonb, 'Cells that exit G₁ enter the quiescent G₀ stage.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('0740b7c1-a5d9-509a-8553-274ddcb891ef', 'neet_ug', 'Botany', 'Photosynthesis in Higher Plants', 'Which of the following statements is incorrect?', '[{"id": "a", "text": "Stroma lamellae have PS I only and lack NADP reductase."}, {"id": "b", "text": "Grana lamellae have both PS I and PS II."}, {"id": "c", "text": "Cyclic photophosphorylation involves both PS I and PS II."}, {"id": "d", "text": "Both ATP and NADPH + H⁺ are synthesized during non-cyclic photophosphorylation."}]'::jsonb, 'c', 'Cyclic photophosphorylation involves only PS I.', 'In cyclic flow, electrons from PS I return to PS I through the electron transport chain, so only ATP is made. This happens in the stroma lamellae, which have PS I but lack PS II and NADP reductase. Non-cyclic flow uses both photosystems and produces both ATP and NADPH.', '{"a": "This is true; stroma lamellae lack PS II and NADP reductase.", "b": "This is true; grana lamellae contain both photosystems.", "d": "This is true; the non-cyclic Z-scheme produces both ATP and NADPH."}'::jsonb, 'Cyclic photophosphorylation uses PS I only and produces ATP but no NADPH.', 'med', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('bf4de1a6-4ade-5694-b004-8e31978018ce', 'neet_ug', 'Botany', 'Respiration in Plants', 'Which of the following statements is incorrect?', '[{"id": "a", "text": "In ETC (Electron Transport Chain), one molecule of NADH + H⁺ gives rise to 2 ATP molecules, and one FADH₂ gives rise to 3 ATP molecules."}, {"id": "b", "text": "ATP is synthesized through complex V."}, {"id": "c", "text": "Oxidation - reduction reactions produce proton gradient in respiration."}, {"id": "d", "text": "During aerobic respiration, role of oxygen is limited to the terminal stage."}]'::jsonb, 'a', 'The values are reversed: NADH yields 3 ATP and FADH₂ yields 2 ATP.', 'Electrons from NADH enter at complex I and pump more protons, giving 3 ATP. FADH₂ enters at complex II and gives 2 ATP. ATP synthase is complex V, redox reactions build the proton gradient, and O₂ acts only as the terminal electron acceptor.', '{"b": "This is true; complex V is ATP synthase.", "c": "This is true; redox reactions in the ETC create the proton gradient.", "d": "This is true; oxygen acts only at the end of the chain."}'::jsonb, 'In NCERT accounting, NADH gives 3 ATP and FADH₂ gives 2 ATP.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('38445ccf-951a-5810-b32f-c4a1fca8bb73', 'neet_ug', 'Botany', 'Sexual Reproduction in Flowering Plants', 'In some members of which of the following pairs of families, pollen grains retain their viability for months after release ?', '[{"id": "a", "text": "Poaceae ; Leguminosae"}, {"id": "b", "text": "Poaceae ; Solanaceae"}, {"id": "c", "text": "Rosaceae ; Leguminosae"}, {"id": "d", "text": "Poaceae ; Rosaceae"}]'::jsonb, 'c', 'Pollen of some Rosaceae, Leguminosae and Solanaceae members stays viable for months.', 'NCERT says that in rice and wheat (Poaceae) pollen loses viability within about 30 minutes of release. In some members of Rosaceae, Leguminosae and Solanaceae it stays viable for months. Rosaceae with Leguminosae is the only pair that does not include Poaceae.', '{"a": "Poaceae pollen loses viability within about 30 minutes.", "b": "Poaceae pollen is short-lived.", "d": "Poaceae pollen is short-lived."}'::jsonb, 'Pollen can be stored for years in liquid nitrogen at −196 °C in pollen banks.', 'med', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('86e6a46c-93bd-5596-a003-15a867175b34', 'neet_ug', 'Botany', 'Molecular Basis of Inheritance', 'What is the role of RNA polymerase III in the process of transcription in eukaryotes?', '[{"id": "a", "text": "Transcribes tRNA, 5s rRNA and snRNA"}, {"id": "b", "text": "Transcribes precursor of mRNA"}, {"id": "c", "text": "Transcribes only snRNAs"}, {"id": "d", "text": "Transcribes rRNAs (28S, 18S and 5.8S)"}]'::jsonb, 'a', 'RNA polymerase III transcribes tRNA, 5S rRNA and snRNAs.', 'Eukaryotes have three nuclear RNA polymerases. Pol I makes 28S, 18S and 5.8S rRNA, Pol II makes hnRNA (the precursor of mRNA), and Pol III makes tRNA, 5S rRNA and snRNAs.', '{"b": "RNA polymerase II makes hnRNA.", "c": "Pol III transcribes more than just snRNAs.", "d": "RNA polymerase I makes the 28S, 18S and 5.8S rRNAs."}'::jsonb, 'Pol I makes rRNA, Pol II makes hnRNA, and Pol III makes tRNA, 5S rRNA and snRNA.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('1fc2d242-4753-5395-a31a-d022d45f92e3', 'neet_ug', 'Botany', 'Molecular Basis of Inheritance', 'DNA fingerprinting involves identifying differences in some specific regions in DNA sequence, called as:', '[{"id": "a", "text": "Repetitive DNA"}, {"id": "b", "text": "Single nucleotides"}, {"id": "c", "text": "Polymorphic DNA"}, {"id": "d", "text": "Satellite DNA"}]'::jsonb, 'a', 'NCERT states that DNA fingerprinting identifies differences in repetitive DNA.', 'DNA fingerprinting compares specific regions called repetitive DNA, where a short stretch of DNA is repeated many times. These repeats separate as satellite DNA in density gradient centrifugation, and their copy number varies between individuals.', '{"b": "Single nucleotide differences (SNPs) are not the basis of the classical technique.", "c": "Polymorphism is a property of these regions, not their NCERT name.", "d": "Satellite DNA is the fraction that holds the repeats, but NCERT names the regions ''repetitive DNA''."}'::jsonb, 'VNTRs were used as probes by Alec Jeffreys in DNA fingerprinting.', 'med', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('06ca93d8-523b-5b3a-a412-157e45800aa0', 'neet_ug', 'Botany', 'Molecular Basis of Inheritance', 'Identify the correct statement.', '[{"id": "a", "text": "RNA polymerase binds with Rho factor to terminate the process of transcription in bacteria."}, {"id": "b", "text": "The coding strand in transcription unit is copied to an mRNA."}, {"id": "c", "text": "Split gene arrangement is characteristic of prokaryotes."}, {"id": "d", "text": "In capping, methyl guanosine triphosphate is added to the 3′ end of hnRNA."}]'::jsonb, 'a', 'In bacteria, RNA polymerase associates with the rho factor to terminate transcription.', 'Bacterial RNA polymerase uses the σ factor for initiation and the ρ factor for termination. The template strand, not the coding strand, is copied. Split genes are a eukaryotic feature, and the methyl guanosine cap is added at the 5′ end.', '{"b": "The template (antisense) strand is copied, not the coding strand.", "c": "Split genes with introns are typical of eukaryotes.", "d": "The cap is added at the 5′ end; a poly-A tail is added at the 3′ end."}'::jsonb, 'σ factor works in initiation and ρ factor in termination of bacterial transcription.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('8a743e41-3bb3-5773-87df-cb16d594e5fc', 'neet_ug', 'Zoology', 'Biotechnology: Principles and Processes', 'Plasmid pBR322 has PstI restriction enzyme site within gene ampᴿ that confers ampicillin resistance. If this enzyme is used for inserting a gene for β-galactoside production and the recombinant plasmid is inserted in an E.coli strain', '[{"id": "a", "text": "The transformed cells will have the ability to resist ampicillin as well as produce β-galactoside."}, {"id": "b", "text": "It will lead to lysis of host cell."}, {"id": "c", "text": "It will be able to produce a novel protein with dual ability."}, {"id": "d", "text": "It will not be able to confer ampicillin resistance to host cell."}]'::jsonb, 'd', 'Inserting DNA at the PstI site disrupts ampᴿ, so the transformants lose ampicillin resistance.', 'This is insertional inactivation. A foreign gene ligated into the PstI site inside the ampicillin-resistance gene destroys that gene. The recombinant cells therefore become sensitive to ampicillin but stay resistant to tetracycline.', '{"a": "The ampᴿ gene is disrupted, so ampicillin resistance is lost.", "b": "An inserted gene does not lyse the host.", "c": "No fused protein with dual ability is formed."}'::jsonb, 'Insertional inactivation lets recombinants be selected by the loss of a marker.', 'med', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('f72faba5-d0cc-5770-86ee-74c5b1259e38', 'neet_ug', 'Zoology', 'Biotechnology and its Applications', 'Now a days it is possible to detect the mutated gene causing cancer by allowing radioactive probe to hybridise its complimentary DNA in a clone of cells, followed by its detection using autoradiography because:', '[{"id": "a", "text": "Mutated gene completely and clearly appears on a photographic film."}, {"id": "b", "text": "Mutated gene does not appear on a photographic film as the prober has no complimentarity with it."}, {"id": "c", "text": "Mutated gene does not appear on photographic film as the probe has complimentarity with it."}, {"id": "d", "text": "Mutated gene partially appears on a photographic film."}]'::jsonb, 'b', 'The probe does not pair with the mutated gene, so the mutated clone shows no signal on the film.', 'A radiolabelled probe made for the normal sequence hybridises to the normal DNA, which then shows up on autoradiography. In the clone carrying the mutation the probe has no complementarity and does not bind, so that gene does not appear on the film.', '{"a": "A non-binding probe gives no signal, so the gene cannot appear clearly.", "c": "If the probe were complementary it would bind and give a signal.", "d": "Autoradiography with this probe does not give a partial-signal result."}'::jsonb, 'Probe hybridisation followed by autoradiography is a method of molecular diagnosis.', 'med', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('152b0629-ecee-58a2-8ec0-bf7e73f61853', 'neet_ug', 'Botany', 'Organisms and Populations', 'In the exponential growth equation
Nₜ = N₀eʳᵗ, e represents:', '[{"id": "a", "text": "The base of exponential logarithms"}, {"id": "b", "text": "The base of natural logarithms"}, {"id": "c", "text": "The base of geometric logarithms"}, {"id": "d", "text": "The base of number logarithms"}]'::jsonb, 'b', 'e (≈ 2.718) is the base of natural logarithms.', 'Integrating dN/dt = rN gives Nₜ = N₀eʳᵗ. Here r is the intrinsic rate of natural increase and e = 2.71828 is the base of natural logarithms.', '{"a": "''Exponential logarithms'' is not a defined base.", "c": "''Geometric logarithms'' is not a term.", "d": "''Number logarithms'' is not a term."}'::jsonb, 'Exponential growth gives a J-shaped curve; logistic growth gives an S-shaped curve.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('7a3d2c52-0ac7-5083-95ac-3b0789238f17', 'neet_ug', 'Zoology', 'The Living World', 'Which one of the following belongs to the family Muscidae?', '[{"id": "a", "text": "Grasshopper"}, {"id": "b", "text": "Cockroach"}, {"id": "c", "text": "Housefly"}, {"id": "d", "text": "Fire fly"}]'::jsonb, 'c', 'The housefly, Musca domestica, belongs to the family Muscidae.', 'In NCERT''s taxonomic example, the housefly is placed in genus Musca, family Muscidae, order Diptera and class Insecta.', '{"a": "Grasshoppers are Orthoptera (Acrididae).", "b": "Cockroaches belong to Blattidae.", "d": "Fireflies are beetles of Lampyridae."}'::jsonb, 'Housefly: Musca, Muscidae, Diptera, Insecta, Arthropoda.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('0dd37e84-cd32-5bc0-b92f-9ff54d07a28c', 'neet_ug', 'Zoology', 'Animal Kingdom', 'Which one of the following organisms bears hollow and pneumatic long bones?', '[{"id": "a", "text": "Hemidactylus"}, {"id": "b", "text": "Macropus"}, {"id": "c", "text": "Ornithorhynchus"}, {"id": "d", "text": "Neophron"}]'::jsonb, 'd', 'Neophron (vulture) is a bird, and birds have hollow, pneumatic long bones.', 'Flight adaptations in Aves include long bones that are hollow and filled with air cavities. Hemidactylus is a reptile, while Macropus and Ornithorhynchus are mammals with solid bones.', '{"a": "Hemidactylus (wall lizard) is a reptile.", "b": "Macropus (kangaroo) is a mammal.", "c": "Ornithorhynchus (platypus) is an egg-laying mammal."}'::jsonb, 'Birds have pneumatic bones and air sacs connected to the lungs.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('439958b2-7c7d-51bb-8dbb-8cbc194f6184', 'neet_ug', 'Zoology', 'Animal Kingdom', 'Match the following:
List-I | List-II
(A) Physalia | (i) Pearl oyster
(B) Limulus | (ii) Portuguese Man of War
(C) Ancylostoma | (iii) Living fossil
(D) Pinctada | (iv) Hookworm
Choose the correct answer from the options given below.', '[{"id": "a", "text": "A-iv B-i C-iii D-ii"}, {"id": "b", "text": "A-ii B-iii C-iv D-i"}, {"id": "c", "text": "A-i B-iv C-iii D-ii"}, {"id": "d", "text": "A-ii B-iii C-i D-iv"}]'::jsonb, 'b', 'Physalia is the Portuguese man-of-war, Limulus is a living fossil, Ancylostoma is the hookworm, and Pinctada is the pearl oyster.', 'Physalia is a cnidarian. Limulus (king crab) is an arthropod called a living fossil. Ancylostoma is the aschelminth hookworm, and Pinctada is the molluscan pearl oyster.', '{"a": "Physalia is not a hookworm.", "c": "Physalia is not a pearl oyster.", "d": "Ancylostoma is not a pearl oyster."}'::jsonb, 'Limulus (king crab) is a living fossil.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('d2a82494-4a3c-57c2-8003-13f7b05e6ab3', 'neet_ug', 'Zoology', 'Animal Kingdom', 'Read the following statements.
A. Metagenesis is observed in Helminths.
B. Echinoderms are triploblastic and coelomate animals.
C. Round worms have organ-system level of body organization.
D. Comb plates present in ctenophores help in digestion.
E. Water vascular system is characteristic of Echinoderms.
Choose the correct answer from the options given below.', '[{"id": "a", "text": "A, B and C are correct"}, {"id": "b", "text": "A, D and E are correct"}, {"id": "c", "text": "B, C and E are correct"}, {"id": "d", "text": "C, D and E are correct"}]'::jsonb, 'c', 'B, C and E are true; metagenesis is seen in cnidarians, and comb plates are used for locomotion.', 'Alternation of polyp and medusa generations (metagenesis) occurs in Cnidaria such as Obelia, not in helminths, so A is false. Comb plates help ctenophores swim, so D is false. Echinoderms are triploblastic coelomates with a water vascular system, and aschelminths show organ-system organisation, so B, C and E are true.', '{"a": "A is false; metagenesis does not occur in helminths.", "b": "A and D are false.", "d": "D is false; comb plates are used for locomotion."}'::jsonb, 'Metagenesis (polyp and medusa alternation) occurs in cnidarians such as Obelia.', 'med', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('a55dd72a-5250-5ffe-82b3-4abe4e2bdfd9', 'neet_ug', 'Zoology', 'Structural Organisation in Animals', 'Which of the following characteristics is incorrect with respect to cockroach?', '[{"id": "a", "text": "Hypopharynx lies within the cavity enclosed by the mouth parts."}, {"id": "b", "text": "In females, 7ᵗʰ - 9ᵗʰ sterna together form a genital pouch."}, {"id": "c", "text": "10ᵗʰ abdominal segment in both sexes, bears a pair of anal cerci."}, {"id": "d", "text": "A ring of gastric caeca is present at the junction of midgut and hind gut."}]'::jsonb, 'd', 'Gastric caeca lie at the junction of the foregut and midgut, not the midgut and hindgut.', 'Cockroaches have 6–8 blind gastric caeca at the junction of the foregut (gizzard) and midgut. The Malpighian tubules lie at the junction of the midgut and hindgut. The other three statements are correct NCERT facts.', '{"a": "This is true; the hypopharynx is a tongue-like structure within the mouth parts.", "b": "This is true; the 7th, 8th and 9th sterna form the genital pouch in females.", "c": "This is true; both sexes have anal cerci on the 10th segment."}'::jsonb, 'Malpighian tubules lie at the midgut–hindgut junction.', 'med', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('28207655-dc69-56bf-a7d1-12b31707114f', 'neet_ug', 'Zoology', 'Structural Organisation in Animals', 'Which of the following statements wrongly represents the nature of smooth muscle?', '[{"id": "a", "text": "They are involuntary muscles"}, {"id": "b", "text": "Communication among the cells is performed by intercalated discs"}, {"id": "c", "text": "These muscles are present in the wall of blood vessels"}, {"id": "d", "text": "These muscle have no striations"}]'::jsonb, 'b', 'Intercalated discs are found in cardiac muscle, not smooth muscle.', 'Smooth muscle fibres are spindle-shaped, unstriated and involuntary. They occur in the walls of blood vessels and visceral organs and communicate through gap junctions. Intercalated discs are a feature of cardiac muscle.', '{"a": "This is true; smooth muscle is involuntary.", "c": "This is true; blood vessel walls contain smooth muscle.", "d": "This is true; smooth muscle lacks striations."}'::jsonb, 'Intercalated discs let cardiac muscle cells contract as a unit.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('f67a7574-92e0-54d5-9efe-3058ab3094ad', 'neet_ug', 'Zoology', 'Cell: The Unit of Life', 'The organelles that are included in the endomembrane system are:', '[{"id": "a", "text": "Endoplasmic reticulum, Golgi complex, Lysosomes and Vacuoles."}, {"id": "b", "text": "Golgi complex, Mitochondria, Ribosomes and Lysosomes."}, {"id": "c", "text": "Golgi complex, Endoplasmic reticulum, Mitochondria and Lysosomes."}, {"id": "d", "text": "Endoplasmic reticulum, Mitochondria, Ribosomes and Lysosomes."}]'::jsonb, 'a', 'The endomembrane system is made up of the ER, Golgi complex, lysosomes and vacuoles.', 'These organelles work in a coordinated way, so NCERT groups them as the endomembrane system. Mitochondria, chloroplasts and peroxisomes act independently and are excluded, and ribosomes have no membrane.', '{"b": "Mitochondria and ribosomes are not part of the endomembrane system.", "c": "Mitochondria are not part of the endomembrane system.", "d": "Mitochondria and ribosomes are excluded."}'::jsonb, 'Mitochondria, chloroplasts and peroxisomes are not part of the endomembrane system.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('48f65641-bb54-523d-b992-eb4142771caf', 'neet_ug', 'Zoology', 'Biomolecules', 'Identify the incorrect pair.', '[{"id": "a", "text": "Toxin - Abrin"}, {"id": "b", "text": "Lectins - Concanavalin A"}, {"id": "c", "text": "Drugs - Ricin"}, {"id": "d", "text": "Alkaloids - Codeine"}]'::jsonb, 'c', 'Ricin is a toxin, not a drug.', 'In NCERT''s list of secondary metabolites, abrin and ricin are toxins, concanavalin A is a lectin, codeine is an alkaloid, and vinblastin and curcumin are drugs. So ''Drugs - Ricin'' is the wrong pair.', '{"a": "This is correct; abrin is a toxin.", "b": "This is correct; concanavalin A is a lectin.", "d": "This is correct; codeine is an alkaloid."}'::jsonb, 'Abrin and ricin are toxins; vinblastin and curcumin are drugs.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('2a71c089-4fcd-5db7-b920-d55b575b330b', 'neet_ug', 'Zoology', 'Cell Cycle and Cell Division', 'The fruit fly has 8 chromosomes (2n) in each cell. During interphase of Mitosis if the number of chromosomes at G₁ phase is 8, what would be the number of chromosomes after S phase?', '[{"id": "a", "text": "16"}, {"id": "b", "text": "4"}, {"id": "c", "text": "32"}, {"id": "d", "text": "8"}]'::jsonb, 'd', 'S phase doubles the DNA content but not the chromosome number, so it stays at 8.', 'In S phase each chromosome replicates to form two sister chromatids held together at one centromere. The DNA content goes from 2C to 4C, but the chromosome count stays 2n = 8.', '{"a": "16 would count chromatids, not chromosomes.", "b": "Halving occurs only in meiosis I.", "c": "The number is never quadrupled."}'::jsonb, 'DNA doubles in S phase, but the chromosome number does not change.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('ccf15251-1ea9-5f13-a5cd-ea4618ff7299', 'neet_ug', 'Zoology', 'Cell Cycle and Cell Division', 'Which stage of meiotic prophase shows terminalisation of chiasmata as its distinctive feature?', '[{"id": "a", "text": "Zygotene"}, {"id": "b", "text": "Diakinesis"}, {"id": "c", "text": "Pachytene"}, {"id": "d", "text": "Leptotene"}]'::jsonb, 'b', 'Terminalisation of chiasmata takes place in diakinesis.', 'In diakinesis the chiasmata move towards the ends of the bivalents, the chromosomes condense fully, the spindle forms, and the nuclear envelope and nucleolus disappear.', '{"a": "Zygotene is when synapsis occurs.", "c": "Pachytene is when crossing over occurs.", "d": "Leptotene is when chromosomes begin to condense."}'::jsonb, 'Prophase I stages in order: leptotene, zygotene, pachytene, diplotene, diakinesis.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('2669fbf8-3778-5ee7-9a82-09eb807c49cd', 'neet_ug', 'Zoology', 'Cell Cycle and Cell Division', 'The centriole undergoes duplication during:', '[{"id": "a", "text": "Prophase"}, {"id": "b", "text": "Metaphase"}, {"id": "c", "text": "G₂ phase"}, {"id": "d", "text": "S-phase"}]'::jsonb, 'd', 'In animal cells the centriole duplicates in S phase.', 'NCERT notes that during S phase the centriole duplicates in the cytoplasm at the same time as DNA replicates in the nucleus. The two centrosomes later move apart in prophase.', '{"a": "In prophase the centrosomes migrate to the poles; they do not duplicate then.", "b": "In metaphase chromosomes align at the equator.", "c": "G₂ is for protein synthesis and the centriole has already duplicated."}'::jsonb, 'S phase duplicates both DNA and the centriole in animal cells.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('b575ea96-b31e-5a3c-83f5-085e2b09e4c0', 'neet_ug', 'Zoology', 'Breathing and Exchange of Gases', 'The partial pressures (in mm Hg) of oxygen (O₂) and carbon dioxide (CO₂) at alveoli (the site of diffusion) are:', '[{"id": "a", "text": "pO₂ = 40 and pCO₂ = 45"}, {"id": "b", "text": "pO₂ = 95 and pCO₂ = 40"}, {"id": "c", "text": "pO₂ = 159 and pCO₂ = 0.3"}, {"id": "d", "text": "pO₂ = 104 and pCO₂ = 40"}]'::jsonb, 'd', 'Alveolar air has pO₂ of 104 mm Hg and pCO₂ of 40 mm Hg.', 'From NCERT''s table: atmospheric air is 159/0.3, alveoli are 104/40, deoxygenated blood is 40/45, oxygenated blood is 95/40, and tissues are 40/45 (pO₂/pCO₂ in mm Hg).', '{"a": "40/45 are the values for deoxygenated blood or tissues.", "b": "95/40 are the values for oxygenated blood.", "c": "159/0.3 are the values for atmospheric air."}'::jsonb, 'Alveolar air: pO₂ 104 mm Hg and pCO₂ 40 mm Hg.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('6c2d4b94-48b7-571b-b793-00e9adda5c12', 'neet_ug', 'Zoology', 'Breathing and Exchange of Gases', 'Select the favourable conditions required for the formation of oxyhaemoglobin at the alveoli.', '[{"id": "a", "text": "Low pO₂, high pCO₂, more H⁺, higher temperature"}, {"id": "b", "text": "High pO₂, high pCO₂, less H⁺, higher temperature"}, {"id": "c", "text": "Low pO₂, low pCO₂, more H⁺, higher temperature"}, {"id": "d", "text": "High pO₂, low pCO₂, less H⁺, lower temperature"}]'::jsonb, 'd', 'Oxyhaemoglobin forms best with high pO₂, low pCO₂, fewer H⁺ ions and lower temperature.', 'The conditions in the alveoli (high pO₂, low pCO₂, lower H⁺ and lower temperature) shift the O₂ dissociation curve to the left and favour O₂ binding. The opposite conditions in the tissues favour O₂ release.', '{"a": "These are tissue conditions, which favour dissociation.", "b": "High pCO₂ and higher temperature reduce O₂ binding.", "c": "Low pO₂ and more H⁺ favour release of O₂."}'::jsonb, 'The Bohr effect is a rightward shift of the curve caused by high pCO₂ and H⁺.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('7aa9b6e5-9b72-5fe4-b898-bb1c83f5c98f', 'neet_ug', 'Zoology', 'Body Fluids and Circulation', 'Which enzyme is responsible for the conversion of inactive fibrinogens to fibrins?', '[{"id": "a", "text": "Renin"}, {"id": "b", "text": "Epinephrine"}, {"id": "c", "text": "Thrombokinase"}, {"id": "d", "text": "Thrombin"}]'::jsonb, 'd', 'Thrombin is the enzyme that converts soluble fibrinogen into fibrin threads.', 'Injury triggers formation of thrombokinase, which converts inactive prothrombin into active thrombin (with Ca²⁺). Thrombin then acts on fibrinogen, converting it to insoluble fibrin threads that trap formed elements to form the clot.', '{"a": "Renin is a kidney enzyme acting on angiotensinogen (in humans) or a milk-curdling enzyme in infants.", "b": "Epinephrine is a hormone, not an enzyme.", "c": "Thrombokinase converts prothrombin to thrombin, not fibrinogen to fibrin."}'::jsonb, 'Cascade: thrombokinase → prothrombin to thrombin → fibrinogen to fibrin; Ca²⁺ is essential.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('663a4b5d-f943-59b4-8177-b94d64cec8b4', 'neet_ug', 'Zoology', 'Body Fluids and Circulation', 'Persons with ‘AB’ blood group are called as “Universal recipients”. This is due to:', '[{"id": "a", "text": "Absence of antigens A and B in plasma"}, {"id": "b", "text": "Presence of antibodies, anti-A and anti-B, on RBCs"}, {"id": "c", "text": "Absence of antibodies, anti-A and anti-B, in plasma"}, {"id": "d", "text": "Absence of antigens A and B on the surface of RBCs"}]'::jsonb, 'c', 'AB individuals have no anti-A or anti-B antibodies in plasma, so donor RBCs of any ABO type are not agglutinated.', 'Group AB RBCs carry both A and B antigens, while their plasma lacks both anti-A and anti-B antibodies. Since there is no antibody to attack donor RBC antigens, they can receive blood of any ABO group.', '{"a": "Antigens are on RBC surfaces, not in plasma.", "b": "Antibodies are in plasma, not on RBCs; AB has none anyway.", "d": "AB RBCs carry both A and B antigens."}'::jsonb, 'Group O = universal donor (no antigens); AB = universal recipient (no antibodies).', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('761b2705-34da-5997-83d7-be3d94f0d504', 'neet_ug', 'Zoology', 'Locomotion and Movement', 'Chronic auto immune disorder affecting neuromuscular junction leading to fatigue, weakening and paralysis of skeletal muscle is called as:', '[{"id": "a", "text": "Muscular dystrophy"}, {"id": "b", "text": "Myasthenia gravis"}, {"id": "c", "text": "Gout"}, {"id": "d", "text": "Arthritis"}]'::jsonb, 'b', 'Myasthenia gravis is an autoimmune disorder of the neuromuscular junction.', 'In myasthenia gravis, antibodies act against acetylcholine receptors at the neuromuscular junction, so impulse transmission to skeletal muscle fails, causing fatigue, weakness and paralysis.', '{"a": "Muscular dystrophy is a genetic progressive degeneration of muscle.", "c": "Gout is inflammation of joints due to uric acid crystal deposition.", "d": "Arthritis is inflammation of joints."}'::jsonb, 'Myasthenia gravis: autoimmune, neuromuscular junction; tetany: low Ca²⁺.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('d9e68c65-42d3-5541-a567-cd14d89aa4d7', 'neet_ug', 'Zoology', 'Chemical Coordination and Integration', 'Erythropoietin hormone which stimulates R.B.C. formation is produced by:', '[{"id": "a", "text": "The cells of rostral adenohypophysis"}, {"id": "b", "text": "The cells of bone marrow"}, {"id": "c", "text": "Juxtaglomerular cells of the kidney"}, {"id": "d", "text": "Alpha cells of pancreas."}]'::jsonb, 'c', 'Erythropoietin is secreted by the juxtaglomerular cells of the kidney.', 'NCERT states that the juxtaglomerular cells of the kidney produce a peptide hormone called erythropoietin, which stimulates erythropoiesis (RBC formation) in bone marrow.', '{"a": "Adenohypophysis secretes trophic hormones like GH, TSH, not erythropoietin.", "b": "Bone marrow is the target where RBCs are formed, not the source of the hormone.", "d": "Alpha cells of pancreas secrete glucagon."}'::jsonb, 'Kidney JG cells: erythropoietin (and renin).', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('ea6d4fc3-74f3-5915-9d00-6d39dacb7af1', 'neet_ug', 'Zoology', 'Human Reproduction', 'Receptors for sperm binding in mammals are present on:', '[{"id": "a", "text": "Vitelline membrane"}, {"id": "b", "text": "Perivitelline space"}, {"id": "c", "text": "Zona pellucida"}, {"id": "d", "text": "Corona radiata"}]'::jsonb, 'c', 'Sperm-binding receptors lie in the zona pellucida of the ovum.', 'The sperm contacts the zona pellucida layer of the ovum, whose glycoproteins act as species-specific sperm receptors; binding induces changes that block entry of additional sperms.', '{"a": "The vitelline (plasma) membrane fuses with sperm later but is not where primary binding receptors lie.", "b": "Perivitelline space is a gap, not a receptor-bearing layer.", "d": "Corona radiata is a layer of follicle cells that sperm must pass through."}'::jsonb, 'Fertilisation in ampulla; zona pellucida blocks polyspermy.', 'med', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('d9baf2b1-7e94-5723-b4cf-c8d524d8fc68', 'neet_ug', 'Zoology', 'Reproductive Health', 'Match List-I with List-II.
List-I | List-II
(A) Vaults | (i) Entry of sperm through Cervix is blocked
(B) IUDs | (ii) Removal of Vas deferens
(C) Vasectomy | (iii) Phagocytosis of sperms within the Uterus
(D) Tubectomy | (iv) Removal of fallopian tube
Choose the correct answer from the options given below.', '[{"id": "a", "text": "A-i B-iii C-ii D-iv"}, {"id": "b", "text": "A-ii B-iv C-iii D-i"}, {"id": "c", "text": "A-iii B-i C-iv D-ii"}, {"id": "d", "text": "A-iv B-ii C-i D-iii"}]'::jsonb, 'a', 'Vaults block the cervix, IUDs increase phagocytosis of sperms, vasectomy removes part of vas deferens, tubectomy removes part of fallopian tube.', 'Vaults are barrier devices covering the cervix, blocking sperm entry. IUDs increase phagocytosis of sperms in the uterus. Vasectomy cuts/removes a small part of the vas deferens and tubectomy a small part of the fallopian tube.', '{"b": "Mismatches vaults with vasectomy and IUDs with tubectomy.", "c": "Pairs vaults with phagocytosis, which is the action of IUDs.", "d": "Pairs vaults with tubectomy, which is a surgical method."}'::jsonb, 'Barriers: condoms, diaphragms, cervical caps, vaults; sterilisation: vasectomy/tubectomy.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('36a63527-7d49-5dcc-8387-fa6e66cd9570', 'neet_ug', 'Zoology', 'Reproductive Health', 'Venereal diseases can spread through
A. Using sterile needles
B. Transfusion of blood from infected person
C. Infected mother to foetus
D. Kissing
E. Inheritance
Choose the correct answer from the options given below.', '[{"id": "a", "text": "A, B, C and D only"}, {"id": "b", "text": "B and C only"}, {"id": "c", "text": "A and C only"}, {"id": "d", "text": "A, B and C only"}]'::jsonb, 'b', 'STIs spread by sexual contact, infected blood transfusion and from infected mother to foetus.', 'Besides sexual contact, STIs such as hepatitis B and HIV are transmitted by sharing unsterilised needles, transfusion of infected blood and from infected mother to foetus. Sterile needles, kissing and inheritance do not transmit them, leaving B and C.', '{"a": "Sterile needles and kissing do not transmit STIs.", "c": "Sterile needles are safe; B is missing.", "d": "Sterile needles are safe."}'::jsonb, 'STIs: gonorrhoea, syphilis, genital herpes, chlamydiasis, trichomoniasis, hepatitis B, HIV.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('4c942e47-3b55-533d-9e9a-4c85b1badf34', 'neet_ug', 'Zoology', 'Reproductive Health', 'Which one of the following is an example of Hormone releasing IUD?', '[{"id": "a", "text": "LNG 20"}, {"id": "b", "text": "Cu 7"}, {"id": "c", "text": "Multiload 375"}, {"id": "d", "text": "CuT"}]'::jsonb, 'a', 'LNG-20 is a hormone-releasing IUD.', 'NCERT lists IUDs as non-medicated (Lippes loop), copper-releasing (CuT, Cu7, Multiload 375) and hormone-releasing (Progestasert, LNG-20). LNG-20 releases levonorgestrel.', '{"b": "Cu7 is a copper-releasing IUD.", "c": "Multiload 375 is a copper-releasing IUD.", "d": "CuT is a copper-releasing IUD."}'::jsonb, 'Hormone-releasing IUDs make uterus unsuitable for implantation and cervix hostile to sperms.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('24a4f05b-8c2a-599a-9be6-9903ecebebcf', 'neet_ug', 'Botany', 'Principles of Inheritance and Variation', 'In a cross between a male and female, both heterozygous for sickle cell anaemia gene, what percentage of the progeny will be diseased?', '[{"id": "a", "text": "75%"}, {"id": "b", "text": "25%"}, {"id": "c", "text": "100%"}, {"id": "d", "text": "50%"}]'::jsonb, 'b', 'Hbᴬ Hbˢ × Hbᴬ Hbˢ gives 1/4 Hbˢ Hbˢ (diseased).', 'Sickle cell anaemia is autosomal recessive; heterozygotes are carriers. The cross Hbᴬ Hbˢ × Hbᴬ Hbˢ gives 1 Hbᴬ Hbᴬ : 2 Hbᴬ Hbˢ : 1 Hbˢ Hbˢ, so 25% are affected.', '{"a": "75% is the proportion carrying at least one normal allele.", "c": "Only homozygous recessives are diseased.", "d": "50% is the proportion of carriers."}'::jsonb, 'Sickle cell: GAG→GUG, Glu→Val at 6th position of β-globin.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('3c51da22-538f-578b-ae62-9c82125b0b55', 'neet_ug', 'Botany', 'Molecular Basis of Inheritance', 'If Adenine makes 30% of the DNA molecule, what will be the percentage of Thymine, Guanine and Cytosine in it?', '[{"id": "a", "text": "T : 20; G : 20; C : 30"}, {"id": "b", "text": "T : 30; G : 20; C : 20"}, {"id": "c", "text": "T : 20; G : 25; C : 25"}, {"id": "d", "text": "T : 20; G : 30; C : 20"}]'::jsonb, 'b', 'By Chargaff''s rule T = A = 30%, and G = C = (100 − 60)/2 = 20%.', 'In double-stranded DNA A = T and G = C. With A = 30%, T = 30%, so A + T = 60%, leaving 40% to be shared equally: G = C = 20%.', '{"a": "T must equal A (30%), and G must equal C.", "c": "T must equal A; percentages sum to 100 only with T = 30.", "d": "G must equal C."}'::jsonb, 'Chargaff: A = T, G = C, purines = pyrimidines.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('cb6901f7-6899-57ab-8f8d-4ce5933cdc7c', 'neet_ug', 'Botany', 'Molecular Basis of Inheritance', 'Which is the “Only enzyme” that has “Capability” to catalyse Initiation, Elongation and Termination in the process of transcription in prokaryotes?', '[{"id": "a", "text": "DNA dependent RNA polymerase"}, {"id": "b", "text": "DNA Ligase"}, {"id": "c", "text": "DNase"}, {"id": "d", "text": "DNA dependent DNA polymerase"}]'::jsonb, 'a', 'A single DNA-dependent RNA polymerase catalyses all steps of bacterial transcription.', 'In bacteria one DNA-dependent RNA polymerase transcribes all RNA types; it associates with σ factor for initiation and ρ factor for termination, but the same enzyme catalyses initiation, elongation and termination.', '{"b": "DNA ligase joins DNA fragments.", "c": "DNase degrades DNA.", "d": "DNA-dependent DNA polymerase replicates DNA."}'::jsonb, 'Eukaryotes have RNA pol I (rRNA), II (hnRNA), III (tRNA, 5S rRNA, snRNA).', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('6ae81f04-3b51-5506-84f1-3ca4e55e2cd0', 'neet_ug', 'Botany', 'Molecular Basis of Inheritance', 'Which of the following RNAs is not required for the synthesis of protein?', '[{"id": "a", "text": "tRNA"}, {"id": "b", "text": "rRNA"}, {"id": "c", "text": "siRNA"}, {"id": "d", "text": "mRNA"}]'::jsonb, 'c', 'siRNA functions in RNA interference (gene silencing), not in translation.', 'Translation needs mRNA as template, tRNA as adapter carrying amino acids and rRNA as structural and catalytic part of ribosomes. siRNA is involved in RNAi-mediated silencing of specific mRNAs.', '{"a": "tRNA carries amino acids.", "b": "rRNA forms ribosomes and acts as ribozyme (peptidyl transferase).", "d": "mRNA provides the codons."}'::jsonb, 'RNAi: dsRNA → siRNA silences target mRNA (used against Meloidogyne incognita).', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('74bacfa1-356f-51bc-be24-7b249090ec12', 'neet_ug', 'Botany', 'Microbes in Human Welfare', 'Match List-I with List-II.
List-I | List-II
(A) Aspergillus niger | (i) Acetic Acid
(B) Acetobacter aceti | (ii) Lactic Acid
(C) Clostridium butylicum | (iii) Citric Acid
(D) Lactobacillus | (iv) Butyric acid
Choose the correct answer from the options given below.', '[{"id": "a", "text": "A-i B-ii C-iii D-iv"}, {"id": "b", "text": "A-ii B-iii C-i D-iv"}, {"id": "c", "text": "A-iv B-ii C-i D-iii"}, {"id": "d", "text": "A-iii B-i C-iv D-ii"}]'::jsonb, 'd', 'Aspergillus niger–citric acid, Acetobacter aceti–acetic acid, Clostridium butylicum–butyric acid, Lactobacillus–lactic acid.', 'These are NCERT examples of microbes producing organic acids industrially: Aspergillus niger (fungus) gives citric acid, Acetobacter aceti gives acetic acid, Clostridium butylicum gives butyric acid and Lactobacillus gives lactic acid.', '{"a": "Aspergillus does not make acetic acid.", "b": "Acetobacter makes acetic, not citric acid.", "c": "Aspergillus does not make butyric acid."}'::jsonb, 'Statins from Monascus purpureus; cyclosporin A from Trichoderma polysporum.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('0f027f9d-f674-52c3-8f6a-a345cf00e3f9', 'neet_ug', 'Zoology', 'Biotechnology: Principles and Processes', 'During the process of gene amplification using PCR, if very high temperature is not maintained in the beginning, then which of the following steps of PCR will be affected first?', '[{"id": "a", "text": "Extension"}, {"id": "b", "text": "Denaturation"}, {"id": "c", "text": "Ligation"}, {"id": "d", "text": "Annealing"}]'::jsonb, 'b', 'The first PCR step, denaturation, needs high temperature to separate DNA strands.', 'PCR cycles through denaturation (~94 °C) to separate the double helix, annealing of primers at lower temperature, and extension by Taq polymerase. Without high temperature at the start, the strands won''t separate, so denaturation fails first.', '{"a": "Extension comes after annealing and uses ~72 °C.", "c": "Ligation is not a PCR step.", "d": "Annealing occurs at a lower temperature and follows denaturation."}'::jsonb, 'Taq polymerase from Thermus aquaticus is thermostable.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('38c644ac-bd81-5622-b6a6-ea0be0695975', 'neet_ug', 'Zoology', 'Biotechnology: Principles and Processes', 'A specific recognition sequence identified by endonucleases to make cuts at specific positions within the DNA is:', '[{"id": "a", "text": "Okazaki sequences"}, {"id": "b", "text": "Palindromic Nucleotide sequences"}, {"id": "c", "text": "Poly (A) tail sequences"}, {"id": "d", "text": "Degenerate primer sequence"}]'::jsonb, 'b', 'Restriction endonucleases recognise palindromic nucleotide sequences.', 'Each restriction endonuclease inspects DNA and binds a specific palindromic sequence, one that reads the same on both strands in the 5′→3′ direction, then cuts within or near it.', '{"a": "Okazaki fragments are lagging-strand replication products.", "c": "Poly(A) tails are added to eukaryotic mRNA.", "d": "Degenerate primers are used in PCR, not recognised by restriction enzymes."}'::jsonb, 'EcoRI recognises 5′-GAATTC-3′, producing sticky ends.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('7e40b7a7-978e-532c-9c54-0adb1cb721bd', 'neet_ug', 'Zoology', 'Biotechnology and Its Applications', 'With regard to insulin choose correct options.
A. C-peptide is not present in mature insulin.
B. The insulin produced by rDNA technology has C-peptide.
C. The pro-insulin has C-peptide.
D. A-peptide and B-peptide of insulin are interconnected by disulphide bridges.
Choose the correct answer from the options given below.', '[{"id": "a", "text": "B and C only"}, {"id": "b", "text": "A, C and D only"}, {"id": "c", "text": "A and C only"}, {"id": "d", "text": "B and D only"}]'::jsonb, 'b', 'Pro-insulin has a C-peptide that is removed in mature insulin; A and B chains are joined by disulphide bonds.', 'Insulin is made as pro-insulin containing an extra C-peptide, removed on maturation; mature insulin has chains A and B linked by disulphide bridges. Eli Lilly produced chains A and B separately and joined them, so rDNA insulin lacks C-peptide. Thus A, C, D are correct.', '{"a": "B is false: recombinant insulin has no C-peptide.", "c": "Omits correct statement D.", "d": "B is false."}'::jsonb, 'Humulin (1983, Eli Lilly) made by expressing A and B chains in E. coli.', 'med', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('55754799-44cc-5d5b-a774-b67862c163e0', 'neet_ug', 'Zoology', 'Biotechnology and Its Applications', 'For effective treatment of the disease, early diagnosis and understanding its pathophysiology is very important. Which of the following molecular diagnostic techniques is very useful for early detection?', '[{"id": "a", "text": "Southern Blotting Technique"}, {"id": "b", "text": "ELISA Technique"}, {"id": "c", "text": "Hybridization Technique"}, {"id": "d", "text": "Western Blotting Technique"}]'::jsonb, 'b', 'ELISA is named in NCERT as a technique for early disease diagnosis.', 'NCERT lists recombinant DNA technology, PCR and ELISA as techniques for early diagnosis. ELISA detects antigens or antibodies produced against the pathogen, so infection can be detected early.', '{"a": "Southern blotting is used for DNA fingerprinting, not listed for early detection.", "c": "Probe hybridisation detects mutated genes but is not the technique NCERT names for early detection.", "d": "Western blotting detects proteins and is used to confirm, not for early screening."}'::jsonb, 'ELISA works on antigen–antibody interaction.', 'med', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('a8d79a91-57e1-5ae9-84f0-d8bf73b47dea', 'neet_ug', 'Zoology', 'Structural Organisation in Animals', 'Identify the types of cell junctions that help to stop the leakage of the substances across a tissue and facilitation of communication with neighbouring cells via rapid transfer of ions and molecules.', '[{"id": "a", "text": "Tight junctions and Gap junctions, respectively."}, {"id": "b", "text": "Adhering junctions and Tight junctions, respectively."}, {"id": "c", "text": "Adhering junctions and Gap junctions, respectively."}, {"id": "d", "text": "Gap junctions and Adhering junctions, respectively."}]'::jsonb, 'a', 'Tight junctions prevent leakage; gap junctions allow rapid exchange between cells.', 'Tight junctions seal neighbouring cells to stop substances leaking across a tissue. Adhering junctions cement cells together. Gap junctions connect cytoplasm of adjoining cells for rapid transfer of ions, small molecules and sometimes big molecules.', '{"b": "Adhering junctions provide cementing, not leakage prevention.", "c": "Adhering junctions do not stop leakage.", "d": "Order reversed and adhering junctions do not aid communication."}'::jsonb, 'Three junctions in epithelium: tight, adhering, gap.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('80778a1e-ffba-5eb1-a446-0dfbea7590d5', 'neet_ug', 'Zoology', 'Structural Organisation in Animals', 'Following are the statements about prostomium of earthworm.
A. It serves as a covering for mouth.
B. It helps to open cracks in the soil into which it can crawl.
C. It is one of the sensory structures.
D. It is the first body segment.
Choose the correct answer from the options given below.', '[{"id": "a", "text": "A, B and D are correct"}, {"id": "b", "text": "A, B, C and D are correct"}, {"id": "c", "text": "B and C are correct"}, {"id": "d", "text": "A, B and C are correct"}]'::jsonb, 'd', 'The prostomium covers the mouth, acts as a wedge into soil cracks and is sensory, but it is not a segment.', 'NCERT describes the prostomium as a lobe covering the mouth that works as a wedge to force open cracks in soil, and as sensory in function. The first body segment is the peristomium (buccal segment), so D is wrong.', '{"a": "D is incorrect: the first segment is the peristomium.", "b": "D is incorrect.", "c": "Omits correct statement A."}'::jsonb, 'Earthworm: clitellum segments 14–16; peristomium contains mouth.', 'med', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('5dcba3c4-39f2-5b88-b137-1f70c5517fd1', 'neet_ug', 'Botany', 'Biomolecules', 'Following are the statements with reference to ‘lipids’.
A. Lipids having only single bonds are called unsaturated fatty acids.
B. Lecithin is a phospholipid.
C. Trihydroxy propane is glycerol.
D. Palmitic acid has 20 carbon atoms including carboxyl carbon.
E. Arachidonic acid has 16 carbon atoms.
Choose the correct answer from the options given below.', '[{"id": "a", "text": "C and D only"}, {"id": "b", "text": "B and C only"}, {"id": "c", "text": "B and E only"}, {"id": "d", "text": "A and B only"}]'::jsonb, 'b', 'Lecithin is a phospholipid and glycerol is trihydroxy propane; the other statements are wrong.', 'Fatty acids with only single bonds are saturated, so A is wrong. Lecithin is a phospholipid and glycerol is trihydroxy propane (B, C correct). Palmitic acid has 16 carbons and arachidonic acid has 20, so D and E are swapped and wrong.', '{"a": "D is wrong: palmitic acid has 16 C.", "c": "E is wrong: arachidonic acid has 20 C.", "d": "A is wrong: single bonds only = saturated."}'::jsonb, 'Palmitic acid C16 (incl. carboxyl C); arachidonic acid C20.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('bc6b7f44-62c4-5247-807e-16a191719342', 'neet_ug', 'Zoology', 'Locomotion and Movement', 'During muscular contraction which of the following events occur?
A. ‘H’ zone disappears
B. ‘A’ band widens
C. ‘I’ band reduces in width
D. Myosine hydrolyzes ATP, releasing the ADP and Pi
E. Z-lines attached to actins are pulled inwards
Choose the correct answer from the options given below.', '[{"id": "a", "text": "A, B, C, D only"}, {"id": "b", "text": "B, C, D, E only"}, {"id": "c", "text": "B, D, E, A only"}, {"id": "d", "text": "A, C, D, E only"}]'::jsonb, 'd', 'During contraction the H zone disappears, I band shortens, ATP is hydrolysed by myosin and Z-lines are pulled in; A band stays the same.', 'As thin filaments slide over thick filaments, Z-lines are pulled inward, the sarcomere shortens, I bands reduce and the H zone disappears. The A band keeps its length because thick filaments do not change. Myosin head ATPase hydrolyses ATP into ADP and Pi to energise cross-bridges.', '{"a": "B is wrong: A band length remains unchanged.", "b": "B is wrong.", "c": "B is wrong."}'::jsonb, 'Sliding filament theory: A band constant; I band and H zone shorten.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('b6cea16a-e6a7-520a-9606-0605cbd8f692', 'neet_ug', 'Zoology', 'Locomotion and Movement', 'Match List-I with List-II.
List-I | List-II
(A) Scapula | (i) Cartilaginous joints
(B) Cranium | (ii) Flat bone
(C) Sternum | (iii) Fibrous joints
(D) Vertebral column | (iv) Triangular flat bone
Choose the correct answer from the options given below.', '[{"id": "a", "text": "A-ii B-iii C-iv D-i"}, {"id": "b", "text": "A-iv B-ii C-iii D-i"}, {"id": "c", "text": "A-iv B-iii C-ii D-i"}, {"id": "d", "text": "A-i B-iii C-ii D-iv"}]'::jsonb, 'c', 'Scapula is a triangular flat bone, cranial bones meet at fibrous joints, sternum is a flat bone and vertebrae have cartilaginous joints.', 'The scapula is a large triangular flat bone on the dorsal thorax. Cranial bones are joined by fibrous sutures (immovable). The sternum is a flat bone on the ventral midline, and adjacent vertebrae are joined by cartilaginous joints.', '{"a": "Scapula is the triangular flat bone, not just a flat bone; sternum is not triangular.", "b": "Cranium is linked to fibrous joints, sternum is not a joint.", "d": "Scapula is not a cartilaginous joint."}'::jsonb, 'Fibrous joints: skull sutures; cartilaginous: between vertebrae; synovial: freely movable.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('8ffe7e3e-4a34-5e04-bcef-50bdbbed4a6d', 'neet_ug', 'Zoology', 'Human Reproduction', 'Which of these is not an important component of initiation of parturition in humans?', '[{"id": "a", "text": "Synthesis of prostaglandins"}, {"id": "b", "text": "Release of Oxytocin"}, {"id": "c", "text": "Release of Prolactin"}, {"id": "d", "text": "Increase in estrogen and progesterone ratio"}]'::jsonb, 'c', 'Prolactin governs milk production, not the onset of labour.', 'Parturition is triggered by a neuroendocrine mechanism: signals from the fully developed foetus and placenta cause mild contractions (foetal ejection reflex), oxytocin release, and a rising oestrogen/progesterone ratio with prostaglandins enhancing uterine contraction. Prolactin is for lactation.', '{"a": "Prostaglandins aid uterine contractions.", "b": "Oxytocin causes strong uterine contractions.", "d": "A higher oestrogen:progesterone ratio promotes contractions."}'::jsonb, 'Foetal ejection reflex → oxytocin from posterior pituitary.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('0c4adb76-39ff-5627-8770-260b37614759', 'neet_ug', 'Zoology', 'Human Reproduction', 'Which of the following secretes the hormone, relaxin during the later phase of pregnancy?', '[{"id": "a", "text": "Corpus luteum"}, {"id": "b", "text": "Foetus"}, {"id": "c", "text": "Uterus"}, {"id": "d", "text": "Graafian follicle"}]'::jsonb, 'a', 'Relaxin in later pregnancy is secreted by the ovary, i.e. the corpus luteum.', 'NCERT notes that relaxin is secreted by the ovary in the later phase of pregnancy; the ovarian source is the corpus luteum. Relaxin softens the pubic symphysis and cervix to ease birth.', '{"b": "The foetus does not secrete relaxin.", "c": "The uterus is the target, not the source.", "d": "The Graafian follicle has ruptured into the corpus luteum by then."}'::jsonb, 'Placental hormones: hCG, hPL, oestrogens, progestogens; relaxin from ovary/corpus luteum.', 'med', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('555ea6b8-5011-5890-8d04-a90664c2e2c8', 'neet_ug', 'Botany', 'Molecular Basis of Inheritance', 'Statement I: The codon ‘AUG’ codes for methionine and phenylalanine.
Statement II: ‘AAA’ and ‘AAG’ both codons code for the amino acid lysine.
In the light of the above statements, choose the correct answer from the options given below.', '[{"id": "a", "text": "Both statement I and statement II are false"}, {"id": "b", "text": "Statement I is correct but statement II is false"}, {"id": "c", "text": "Statement I is incorrect but statement II is true"}, {"id": "d", "text": "Both statement I and statement II are true"}]'::jsonb, 'c', 'AUG codes only for methionine; AAA and AAG both code for lysine.', 'The genetic code is unambiguous: each codon codes for a single amino acid, so AUG means only methionine (and acts as start codon); phenylalanine is UUU/UUC. The code is degenerate, and AAA and AAG both specify lysine.', '{"a": "Statement II is true.", "b": "Statement I is wrong, II is right.", "d": "Statement I is wrong."}'::jsonb, 'Code is unambiguous, degenerate, universal (mostly), comma-less.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('61d5929c-35f1-5111-ad11-9141c9e45ad8', 'neet_ug', 'Botany', 'Molecular Basis of Inheritance', 'Which one of the following statement about histones is wrong?', '[{"id": "a", "text": "The pH of histones is slightly acidic."}, {"id": "b", "text": "Histones are rich in amino acids - Lysine and Arginine."}, {"id": "c", "text": "Histones carry positive charge in the side chain."}, {"id": "d", "text": "Histones are organized to form a unit of 8 molecules."}]'::jsonb, 'a', 'Histones are basic proteins, not acidic.', 'Histones are rich in basic amino acids lysine and arginine, whose side chains carry positive charges, making histones basic. Eight histone molecules form the histone octamer around which DNA wraps in a nucleosome.', '{"b": "True: lysine and arginine are abundant.", "c": "True: basic side chains are positively charged.", "d": "True: histone octamer."}'::jsonb, 'Nucleosome: ~200 bp DNA around histone octamer; H1 is linker histone.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('deabd333-a8ae-5874-81fa-e67e325d7d5c', 'neet_ug', 'Zoology', 'Evolution', 'Match the following:
List-I | List-II
(A) Adaptive radiation | (i) Selection of resistant varieties due to excessive use of herbicides and pesticides
(B) Convergent evolution | (ii) Bones of forelimbs in Man and Whale
(C) Divergent evolution | (iii) Wings of Butterfly and Bird
(D) Evolution by anthropogenic action | (iv) Darwin Finches
Choose the correct answer from the options given below.', '[{"id": "a", "text": "A-iii B-ii C-i D-iv"}, {"id": "b", "text": "A-ii B-i C-iv D-iii"}, {"id": "c", "text": "A-i B-iv C-iii D-ii"}, {"id": "d", "text": "A-iv B-iii C-ii D-i"}]'::jsonb, 'd', 'Darwin''s finches show adaptive radiation; butterfly and bird wings show convergence; forelimb bones show divergence; pesticide resistance is anthropogenic evolution.', 'Darwin''s finches radiated from a seed-eating ancestor into many forms. Butterfly and bird wings are analogous (convergent evolution), while homologous forelimbs of man and whale reflect divergent evolution. Herbicide/pesticide resistance arises from human-driven selection.', '{"a": "Adaptive radiation is not shown by butterfly/bird wings.", "b": "Forelimb bones show divergence, not adaptive radiation as listed.", "c": "Herbicide resistance is anthropogenic, not adaptive radiation."}'::jsonb, 'Homology → divergent evolution; analogy → convergent evolution.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('b578d554-e5c8-5f99-890a-0133d49ff473', 'neet_ug', 'Zoology', 'Human Health and Disease', 'Match the following:
List-I | List-II
(A) Filariasis | (i) Haemophilus influenzae
(B) Amoebiasis | (ii) Trichophyton
(C) Pneumonia | (iii) Wuchereria bancrofti
(D) Ringworm | (iv) Entamoeba histolytica
Choose the correct answer from the options given below.', '[{"id": "a", "text": "A-iii B-iv C-i D-ii"}, {"id": "b", "text": "A-i B-ii C-iv D-iii"}, {"id": "c", "text": "A-ii B-iii C-i D-iv"}, {"id": "d", "text": "A-iv B-i C-iii D-ii"}]'::jsonb, 'a', 'Filariasis–Wuchereria, amoebiasis–Entamoeba, pneumonia–Haemophilus, ringworm–Trichophyton.', 'Filariasis (elephantiasis) is caused by the nematode Wuchereria bancrofti; amoebic dysentery by Entamoeba histolytica; pneumonia by Streptococcus pneumoniae and Haemophilus influenzae; ringworm by fungi such as Trichophyton, Microsporum and Epidermophyton.', '{"b": "Filariasis is not bacterial.", "c": "Filariasis is not fungal.", "d": "Filariasis is not caused by Entamoeba."}'::jsonb, 'Ascariasis, filariasis: helminths; ringworm: fungi.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('25681acb-f81d-5a76-8a8b-5cbe523b3995', 'neet_ug', 'Zoology', 'Biotechnology and Its Applications', 'The adenosine deaminase deficiency results into:', '[{"id": "a", "text": "Parkinson’s disease"}, {"id": "b", "text": "Digestive disorder"}, {"id": "c", "text": "Addison’s disease"}, {"id": "d", "text": "Dysfunction of Immune system"}]'::jsonb, 'd', 'ADA deficiency causes severe combined immunodeficiency.', 'Adenosine deaminase is crucial for the immune system; its deficiency, caused by deletion of the ADA gene, leads to SCID. It was the first disease treated by gene therapy (1990) using lymphocytes carrying a functional ADA cDNA.', '{"a": "Parkinson''s is a dopaminergic neuron disorder.", "b": "ADA deficiency is not a digestive disorder.", "c": "Addison''s disease is adrenal cortex insufficiency."}'::jsonb, 'First gene therapy: 1990, 4-year-old girl with ADA deficiency.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('ea4a1a2f-a09f-5029-b01f-122bb3bb0131', 'neet_ug', 'Botany', 'Organisms and Populations', 'Match List-I with List-II:
List-I | List-II
(A) Allen’s Rule | (i) Kangaroo rat
(B) Physiological adaptation | (ii) Desert lizard
(C) Behavioural adaptation | (iii) Marine fish at depth
(D) Biochemical adaptation | (iv) Polar seal
Choose the correct answer from the options given below.', '[{"id": "a", "text": "A-iv B-i C-iii D-ii"}, {"id": "b", "text": "A-iv B-i C-ii D-iii"}, {"id": "c", "text": "A-iv B-iii C-ii D-i"}, {"id": "d", "text": "A-iv B-ii C-iii D-i"}]'::jsonb, 'b', 'Polar seal–Allen''s rule, kangaroo rat–physiological, desert lizard–behavioural, deep-sea fish–biochemical.', 'Mammals of cold climates such as seals have shorter extremities to reduce heat loss (Allen''s rule). Kangaroo rats meet water needs by internal fat oxidation and concentrated urine (physiological). Desert lizards bask or burrow to regulate temperature (behavioural). Deep-sea fish have biochemical adaptations to high pressure.', '{"a": "Kangaroo rat is physiological, but desert lizard is behavioural, not deep-sea fish.", "c": "Physiological adaptation is the kangaroo rat, not deep-sea fish.", "d": "Desert lizard is behavioural, not physiological."}'::jsonb, 'Seals have thick blubber and short limbs to conserve heat.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('fdf7ebb4-7904-5d39-a024-41361ff8a8b4', 'neet_ug', 'Chemistry', 'Structure of Atom', 'A particular station of All India Radio, New Delhi, broadcasts on a frequency of 1,368 kHz (kilohertz). The wavelength of the electromagnetic radiation emitted by the transmitter is:
[speed of light, c = 3.0 × 10⁸ ms⁻¹]', '[{"id": "a", "text": "219.2 m"}, {"id": "b", "text": "2192 m"}, {"id": "c", "text": "21.92 cm"}, {"id": "d", "text": "219.3 m"}]'::jsonb, 'd', 'λ = c/ν = 3.0 × 10⁸ / 1.368 × 10⁶ ≈ 219.3 m.', 'ν = 1368 kHz = 1.368 × 10⁶ s⁻¹. λ = c/ν = (3.0 × 10⁸)/(1.368 × 10⁶) = 219.30 m.', '{"a": "Rounding error; the value is 219.30 m.", "b": "Off by a factor of 10.", "c": "Wrong units and magnitude."}'::jsonb, 'c = νλ; radio waves have wavelengths of metres to km.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('d1602ed8-7cdf-59fa-9296-a48251a71854', 'neet_ug', 'Chemistry', 'Chemical Bonding and Molecular Structure', 'BF₃ is planar and electron deficient compound. Hybridization and number of electrons around the central atom, respectively are:', '[{"id": "a", "text": "sp³ and 6"}, {"id": "b", "text": "sp² and 6"}, {"id": "c", "text": "sp² and 8"}, {"id": "d", "text": "sp³ and 4"}]'::jsonb, 'b', 'Boron in BF₃ is sp² hybridised with only 6 valence electrons around it.', 'Boron has 3 valence electrons and forms three B–F σ bonds with no lone pair, giving 3 electron domains → sp² and trigonal planar. Three bond pairs mean 6 electrons around B, an incomplete octet.', '{"a": "BF₃ is not sp³; it is planar.", "c": "Boron does not complete its octet in BF₃.", "d": "Wrong hybridisation and electron count."}'::jsonb, 'BF₃, BeCl₂, AlCl₃ (monomer): incomplete octets; Lewis acids.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('98d1df69-fa79-59c9-aa02-f9f9b6052176', 'neet_ug', 'Chemistry', 'Chemical Bonding and Molecular Structure', 'Match List-I with List-II.
List-I | List-II
(A) PCl₅ | (i) Square pyramidal
(B) SF₆ | (ii) Trigonal planar
(C) BrF₅ | (iii) Octahedral
(D) BF₃ | (iv) Trigonal bipyramidal
Choose the correct answer from the options given below.', '[{"id": "a", "text": "A-ii B-iii C-iv D-i"}, {"id": "b", "text": "A-iii B-i C-iv D-ii"}, {"id": "c", "text": "A-iv B-iii C-ii D-i"}, {"id": "d", "text": "A-iv B-iii C-i D-ii"}]'::jsonb, 'd', 'PCl₅ trigonal bipyramidal, SF₆ octahedral, BrF₅ square pyramidal, BF₃ trigonal planar.', 'PCl₅: 5 bond pairs, sp³d → trigonal bipyramidal. SF₆: 6 bond pairs, sp³d² → octahedral. BrF₅: 5 bond pairs + 1 lone pair, sp³d² → square pyramidal. BF₃: 3 bond pairs, sp² → trigonal planar.', '{"a": "PCl₅ is not trigonal planar.", "b": "PCl₅ is not octahedral.", "c": "BrF₅ is not trigonal planar; BF₃ is not square pyramidal."}'::jsonb, 'VSEPR: lone pairs change shape (BrF₅, XeF₄, ClF₃).', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('038d4723-d56c-5ccc-af3c-f83c78998c53', 'neet_ug', 'Chemistry', 'Thermodynamics', 'Which one among the following is the correct option for right relationship between Cₚ and Cᵥ for one mole of ideal gas?', '[{"id": "a", "text": "Cₚ − Cᵥ = R"}, {"id": "b", "text": "Cₚ = RCᵥ"}, {"id": "c", "text": "Cᵥ = RCₚ"}, {"id": "d", "text": "Cₚ + Cᵥ = R"}]'::jsonb, 'a', 'For one mole of an ideal gas, Cₚ − Cᵥ = R (Mayer''s relation).', 'At constant pressure, heating also does expansion work. Since ΔH = ΔU + Δ(pV) = ΔU + RΔT per mole, Cₚ ΔT = Cᵥ ΔT + R ΔT, giving Cₚ − Cᵥ = R.', '{"b": "Not dimensionally consistent: R has units of heat capacity.", "c": "Not dimensionally consistent.", "d": "Cₚ is greater than Cᵥ; the difference, not the sum, equals R."}'::jsonb, 'Cₚ > Cᵥ; for monoatomic gas Cᵥ = 3R/2, Cₚ = 5R/2.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('946a1be0-bb6f-521e-b51c-8afafc8e1060', 'neet_ug', 'Chemistry', 'Equilibrium', 'The pK_b of dimethylamine and pK_a of acetic acid are 3.27 and 4.77 respectively at T(K). The correct option for the pH of dimethylammonium acetate solution is:', '[{"id": "a", "text": "5.50"}, {"id": "b", "text": "7.75"}, {"id": "c", "text": "6.25"}, {"id": "d", "text": "8.50"}]'::jsonb, 'b', 'For a salt of a weak acid and weak base, pH = 7 + ½(pKa − pKb) = 7.75.', 'Dimethylammonium acetate hydrolyses at both ions, and its pH is independent of concentration: pH = 7 + ½(pKa − pKb). Substituting, pH = 7 + ½(4.77 − 3.27) = 7 + 0.75 = 7.75. The base is slightly stronger than the acid (pKb < pKa), so the solution is mildly basic.', '{"a": "Would need the acid to be stronger than the base.", "c": "Uses 7 − ½(pKa − pKb) wrongly or other sign error.", "d": "Adds the full difference 1.5 instead of half of it."}'::jsonb, 'Salt of weak acid + weak base: pH = 7 + ½(pKa − pKb).', 'med', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('a2e0a7b5-b409-51a2-95d7-05340fef6100', 'neet_ug', 'Chemistry', 'Redox Reactions', 'Which of the following reactions is the metal displacement reaction? Choose the right option.', '[{"id": "a", "text": "Cr₂O₃ + 2Al →(Δ) Al₂O₃ + 2Cr"}, {"id": "b", "text": "Fe + 2HCl → FeCl₂ + H₂↑"}, {"id": "c", "text": "2Pb(NO₃)₂ → 2PbO + 4NO₂ + O₂↑"}, {"id": "d", "text": "2KClO₃ →(Δ) 2KCl + 3O₂"}]'::jsonb, 'a', 'Al displaces Cr from its oxide, so this is a metal displacement reaction.', 'In a metal displacement reaction a more reactive metal replaces another metal from its compound. In the thermite-type reaction, Al reduces Cr₂O₃ and frees metallic Cr. Fe + HCl displaces hydrogen, not a metal, and the other two are thermal decompositions.', '{"b": "Hydrogen displacement, not metal displacement.", "c": "Decomposition reaction.", "d": "Decomposition reaction."}'::jsonb, 'Displacement redox: metal displacement (Al/Cr₂O₃) vs hydrogen displacement (metal + acid).', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('5e3fb6f1-de34-53c6-b04f-9737e8adbff4', 'neet_ug', 'Chemistry', 'Organic Chemistry: Some Basic Principles and Techniques', 'The compound which shows metamerism is:', '[{"id": "a", "text": "C₃H₈O"}, {"id": "b", "text": "C₃H₆O"}, {"id": "c", "text": "C₄H₁₀O"}, {"id": "d", "text": "C₅H₁₂"}]'::jsonb, 'c', 'C₄H₁₀O forms ethers C₂H₅OC₂H₅ and CH₃OC₃H₇, which are metamers.', 'Metamerism arises when different alkyl groups sit on either side of a polyvalent functional group such as –O–. C₄H₁₀O gives diethyl ether and methyl propyl ether, differing only in the alkyl groups around O. C₃H₈O has only one ether (CH₃OC₂H₅), so it cannot show metamerism.', '{"a": "Only one ether, CH₃OCH₂CH₃, is possible.", "b": "Aldehyde/ketone isomers show functional isomerism, not metamerism.", "d": "Alkane with no functional group, only chain isomerism."}'::jsonb, 'Metamers: same functional group, different alkyl groups on either side (ethers, ketones, amines).', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('ee0661b0-968a-52d1-8b99-a1e1e3028376', 'neet_ug', 'Chemistry', 'Organic Chemistry: Some Basic Principles and Techniques', 'The correct structure of 2,6-Dimethyl-dec-4-ene is:', '[{"id": "a", "text": "Option (1) in figure"}, {"id": "b", "text": "Option (2) in figure"}, {"id": "c", "text": "Option (3) in figure"}, {"id": "d", "text": "Option (4) in figure"}]'::jsonb, 'd', 'Structure (d) has a 10-carbon chain with C4=C5 and methyls on C2 and C6.', 'Number from the isopropyl end: C1–C2(CH₃)–C3–C4=C5–C6(CH₃)–C7–C8–C9–C10. In (d), the isopropyl end is followed by one CH₂, then the double bond, then the carbon bearing a methyl, and then a butyl chain, which matches exactly. The other skeletons put the double bond or the methyl branch at the wrong carbon.', '{"a": "Double bond lies away from C4, between the branched carbon and the chain end.", "b": "Double bond is at C3=C4, giving a dec-3-ene.", "c": "Methyl is on a double-bond carbon, which is the wrong locant pattern."}'::jsonb, 'IUPAC: choose the longest chain containing the double bond, give the double bond the lowest locant, then the substituents.', 'med', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', '/pyq/ug/2021/1513.webp'),
('d4059799-e53c-5a60-b9d7-d3ed3cbf91e2', 'neet_ug', 'Chemistry', 'Hydrocarbons', 'Dihedral angle of least stable conformer of ethane is:', '[{"id": "a", "text": "180°"}, {"id": "b", "text": "60°"}, {"id": "c", "text": "0°"}, {"id": "d", "text": "120°"}]'::jsonb, 'c', 'The eclipsed conformer, which is the least stable, has a 0° dihedral angle.', 'In ethane the eclipsed conformation has maximum torsional strain because the C–H bonds of the two carbons are aligned. Its H–C–C–H dihedral angle is 0°. The staggered form (60°) is the most stable.', '{"a": "180° is also a staggered relationship.", "b": "60° is the staggered, most stable conformer.", "d": "120° is another eclipsed position; it is equivalent to 0°, but 0° is the standard answer."}'::jsonb, 'Ethane: staggered (60°) is more stable than eclipsed (0°) by about 12.5 kJ mol⁻¹.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('42632e26-bcc3-5670-aefc-05b835d47bdb', 'neet_ug', 'Chemistry', 'Hydrocarbons', 'The major product of the following chemical reaction is:
(CH₃)₂CH–CH=CH₂ + HBr —(C₆H₅CO)₂O₂→ ?', '[{"id": "a", "text": "(CH₃)₂CH–CH₂–CH₂–O–COC₆H₅"}, {"id": "b", "text": "(CH₃)₂CH–CH(Br)–CH₃"}, {"id": "c", "text": "(CH₃)₂CBr–CH₂–CH₃"}, {"id": "d", "text": "(CH₃)₂CH–CH₂–CH₂–Br"}]'::jsonb, 'd', 'With peroxide, HBr adds anti-Markovnikov to give 1-bromo-3-methylbutane.', 'Benzoyl peroxide starts a free-radical chain. Br• adds to the terminal CH₂ to give the more stable secondary radical, which then takes H from HBr. The result is Br on the terminal carbon: (CH₃)₂CHCH₂CH₂Br. Radicals do not rearrange the way carbocations do here.', '{"a": "The peroxide is only an initiator and is not incorporated.", "b": "This is the Markovnikov product, formed without peroxide.", "c": "This is the product of carbocation rearrangement under ionic conditions."}'::jsonb, 'Kharasch (peroxide) effect works only with HBr, giving anti-Markovnikov addition.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('ea6587dd-c82c-5594-811e-f4c75c063e8d', 'neet_ug', 'Chemistry', 'Solutions', 'The following solutions were prepared by dissolving 10 g of glucose (C₆H₁₂O₆) in 250 ml of water (P₁), 10 g of urea (CH₄N₂O) in 250 ml of water (P₂) and 10 g of sucrose (C₁₂H₂₂O₁₁) in 250 ml of water (P₃). The right option for the decreasing order of osmotic pressure of these solutions is:', '[{"id": "a", "text": "P₁ > P₂ > P₃"}, {"id": "b", "text": "P₂ > P₃ > P₁"}, {"id": "c", "text": "P₃ > P₁ > P₂"}, {"id": "d", "text": "P₂ > P₁ > P₃"}]'::jsonb, 'd', 'π ∝ moles of solute; urea (M 60) > glucose (180) > sucrose (342).', 'At equal mass and volume, π = (w/M)RT/V, so π ∝ 1/M for these non-electrolytes. The moles are urea 10/60 = 0.167, glucose 10/180 = 0.056 and sucrose 10/342 = 0.029. Hence P₂ > P₁ > P₃.', '{"a": "Places glucose above urea, even though urea has the lower molar mass.", "b": "Puts sucrose above glucose.", "c": "Reverses the order."}'::jsonb, 'Colligative properties depend on the number of solute particles: lower molar mass gives a higher π at equal mass.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('d4095688-4cec-5287-a55d-1ddd640f0370', 'neet_ug', 'Chemistry', 'Electrochemistry', 'The molar conductance of NaCl, HCl and CH₃COONa at infinite dilution are 126.45, 426.16 and 91.0 S cm² mol⁻¹ respectively. The molar conductance of CH₃COOH at infinite dilution is. Choose the right option for your answer.', '[{"id": "a", "text": "390.71 S cm² mol⁻¹"}, {"id": "b", "text": "698.28 S cm² mol⁻¹"}, {"id": "c", "text": "540.48 S cm² mol⁻¹"}, {"id": "d", "text": "201.28 S cm² mol⁻¹"}]'::jsonb, 'a', 'Kohlrausch: Λ°(CH₃COOH) = Λ°(CH₃COONa) + Λ°(HCl) − Λ°(NaCl) = 390.71.', 'By Kohlrausch''s law of independent ionic migration, Λ°(CH₃COOH) = 91.0 + 426.16 − 126.45 = 390.71 S cm² mol⁻¹. The Na⁺ and Cl⁻ contributions cancel.', '{"b": "Adds NaCl instead of subtracting it.", "c": "Wrong combination of terms.", "d": "Wrong combination of terms."}'::jsonb, 'Kohlrausch''s law gives Λ° of weak electrolytes from strong-electrolyte data.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('2f396b1e-1d1d-5884-8f44-4dabf33ef42e', 'neet_ug', 'Chemistry', 'Chemical Kinetics', 'For a reaction A → B, enthalpy of reaction is –4.2 kJ mol⁻¹ and enthalpy of activation is 9.6 kJ mol⁻¹. The correct potential energy profile for the reaction is shown in option.', '[{"id": "a", "text": "Option (1) in figure"}, {"id": "b", "text": "Option (2) in figure"}, {"id": "c", "text": "Option (3) in figure"}, {"id": "d", "text": "Option (4) in figure"}]'::jsonb, 'a', 'Exothermic with a modest barrier, so B ends clearly below A with a peak above A.', 'ΔH = −4.2 kJ mol⁻¹ means the product B lies below the reactant A. Ea = 9.6 kJ mol⁻¹ means the hump rises above A by roughly twice that drop. Profile (a) shows exactly this. In (b) A and B are at about the same level, and (c) and (d) show B above A, which would be endothermic.', '{"b": "A and B are at nearly the same energy, so ΔH ≈ 0.", "c": "B is above A, which is endothermic.", "d": "B is slightly above A, which is endothermic."}'::jsonb, 'Ea(reverse) = Ea(forward) − ΔH; for an exothermic reaction the products lie below the reactants.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', '/pyq/ug/2021/1620.webp'),
('369dbb9a-4a11-5db9-adca-1d8daf32a18f', 'neet_ug', 'Chemistry', 'The p-Block Elements', 'Noble gases are named because of their inertness towards reactivity. Identify an incorrect statement about them.', '[{"id": "a", "text": "Noble gases have very high melting and boiling points"}, {"id": "b", "text": "Noble gases have weak dispersion forces"}, {"id": "c", "text": "Noble gases have large positive values of electron gain enthalpy"}, {"id": "d", "text": "Noble gases are sparingly soluble in water"}]'::jsonb, 'a', 'Noble gases have very low melting and boiling points because only weak dispersion forces act between their atoms.', 'Noble gases are monoatomic and held together only by weak London forces, so their m.p. and b.p. are very low. Their stable ns²np⁶ configuration gives a large positive electron gain enthalpy, and they dissolve only slightly in water.', '{"b": "Correct: only weak dispersion forces act.", "c": "Correct: a stable octet resists an added electron.", "d": "Correct: they are sparingly soluble."}'::jsonb, 'Noble gas b.p. rises down the group as polarisability increases, but all values are low.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('ac492600-0f23-5735-8a8e-a07411b18fb8', 'neet_ug', 'Chemistry', 'The p-Block Elements', 'Statement-I: Acid strength increases in the order given as HF << HCl << HBr << HI.
Statement II: As the size of the elements F, Cl, Br, I increases down the group, the bond strength of HF, HCl, HBr and HI decreases and so the acid strength increases.
In the light of the above statements, choose the correct answer from the options given below.', '[{"id": "a", "text": "Both statement I and statement II are false"}, {"id": "b", "text": "Statement I is correct but statement II is false"}, {"id": "c", "text": "Statement I is incorrect but Statement II is true"}, {"id": "d", "text": "Both statement I and statement II are true"}]'::jsonb, 'd', 'Down the group the H–X bond weakens, so acid strength rises from HF to HI; both statements are true.', 'As the halogen gets larger, H–X bond length increases and bond dissociation enthalpy falls, so the bond ionises more easily in water. That gives the order HF < HCl < HBr < HI. Statement II is the correct reason for Statement I.', '{"a": "Both statements are factually correct.", "b": "Statement II is also correct.", "c": "Statement I is also correct."}'::jsonb, 'Hydrogen halide acidity HF < HCl < HBr < HI is governed by bond enthalpy.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('5c670615-b430-56ad-8f2c-b6ed312691d4', 'neet_ug', 'Chemistry', 'The d- and f-Block Elements', 'Zr (Z = 40) and Hf (Z = 72) have similar atomic and ionic radii because of:', '[{"id": "a", "text": "Diagonal relationship"}, {"id": "b", "text": "Lanthanoid contraction"}, {"id": "c", "text": "Having similar chemical properties"}, {"id": "d", "text": "Belonging to same group"}]'::jsonb, 'b', 'Lanthanoid contraction cancels the expected size increase from Zr to Hf.', 'The 14 4f electrons that come before Hf shield the nucleus poorly, so the radius shrinks steadily across the lanthanoids. This offsets the extra shell, which makes the 5d elements nearly the same size as their 4d congeners (Zr 160 pm, Hf 159 pm).', '{"a": "Diagonal relationship refers to period-2/3 pairs such as Li–Mg.", "c": "Similar properties are a consequence, not the cause.", "d": "Same group alone would predict Hf to be larger."}'::jsonb, 'Lanthanoid contraction leads to Zr/Hf, Nb/Ta and Mo/W twin pairs.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('bf4d06cb-47bb-5cf9-8354-3f9c08f08fcb', 'neet_ug', 'Chemistry', 'The d- and f-Block Elements', 'The incorrect statement among the following is:', '[{"id": "a", "text": "Most of the trivalent Lanthanoid ions are colorless in the solid state"}, {"id": "b", "text": "Lanthanoids are good conductors of heat and electricity"}, {"id": "c", "text": "Actinoids are highly reactive metals, especially when finely divided"}, {"id": "d", "text": "Actinoid contraction is greater for element to element than Lanthanoid contraction"}]'::jsonb, 'a', 'Most Ln³⁺ ions are coloured due to f–f transitions; only f⁰/f¹⁴ ions such as La³⁺ and Lu³⁺ are colourless.', 'Trivalent lanthanoid ions with partly filled 4f orbitals absorb visible light and are coloured in the solid state and in solution. Colourless ions are the exception (La³⁺, Lu³⁺, and nearly Ce³⁺/Yb³⁺). The remaining statements agree with NCERT: they are metallic conductors, actinoids are highly reactive, and 5f shielding is poorer, so actinoid contraction per element is larger.', '{"b": "True: they are typical metals.", "c": "True: finely divided actinoids are very reactive.", "d": "True: 5f electrons shield even less effectively."}'::jsonb, 'Ln³⁺ colour comes from f–f transitions; f⁰ and f¹⁴ ions are colourless.', 'med', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('23e8a246-e1b8-55f8-862c-19be6495cee1', 'neet_ug', 'Chemistry', 'Coordination Compounds', 'Ethylene diaminetetraacetate (EDTA) ion is:', '[{"id": "a", "text": "Unidentate ligand"}, {"id": "b", "text": "Bidentate ligand with two \"N\" donor atoms"}, {"id": "c", "text": "Tridentate ligand with three \"N\" donor atoms"}, {"id": "d", "text": "Hexadentate ligand with four \"O\" and two \"N\" donor atoms"}]'::jsonb, 'd', 'EDTA⁴⁻ binds through 2 N and 4 carboxylate O atoms, so it is hexadentate.', 'EDTA⁴⁻ has two tertiary amine N atoms and four –COO⁻ groups, each able to donate one lone pair. It wraps around a metal ion with six donor atoms. This is why it forms very stable chelates, used for example in titrating Ca²⁺/Mg²⁺.', '{"a": "It has six donor sites, not one.", "b": "Ethylenediamine (en) is the bidentate N,N ligand.", "c": "Diethylenetriamine is the N₃ tridentate ligand."}'::jsonb, 'EDTA is hexadentate (N₂O₄) and is used for estimating water hardness.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('c017ee4c-3a1a-5399-b3fa-b77c4b1ce111', 'neet_ug', 'Chemistry', 'Haloalkanes and Haloarenes', 'The correct sequence of bond enthalpy of ''C–X'' bond is:', '[{"id": "a", "text": "CH₃–F > CH₃–Cl > CH₃–Br > CH₃–I"}, {"id": "b", "text": "CH₃–F < CH₃–Cl > CH₃–Br > CH₃–I"}, {"id": "c", "text": "CH₃–Cl > CH₃–F > CH₃–Br > CH₃–I"}, {"id": "d", "text": "CH₃–F < CH₃–Cl < CH₃–Br < CH₃–I"}]'::jsonb, 'a', 'C–X bond enthalpy falls from F to I as bond length increases.', 'As the halogen grows, orbital overlap with carbon gets poorer and the C–X bond lengthens. Bond enthalpy therefore decreases: C–F (~452) > C–Cl (~351) > C–Br (~293) > C–I (~234 kJ mol⁻¹). This is also why iodides are the most reactive in SN reactions.', '{"b": "C–F is the strongest, not weaker than C–Cl.", "c": "C–F is stronger than C–Cl.", "d": "This order is completely reversed."}'::jsonb, 'R–I is the most reactive haloalkane because C–I is the weakest bond.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('1482a9a5-1a2d-53af-a33a-15c7d17b3f24', 'neet_ug', 'Chemistry', 'Haloalkanes and Haloarenes', 'The major product formed in dehydrohalogenation reaction of 2-Bromo pentane is Pent-2-ene. This product formation is based on?', '[{"id": "a", "text": "Hund''s rule"}, {"id": "b", "text": "Hofmann rule"}, {"id": "c", "text": "Huckel''s rule"}, {"id": "d", "text": "Saytzeff''s rule"}]'::jsonb, 'd', 'β-elimination gives the more substituted alkene: Saytzeff''s rule.', 'Alcoholic KOH removes HBr from 2-bromopentane. H can be lost from C1 (giving pent-1-ene) or from C3 (giving pent-2-ene). The more highly substituted, more stable pent-2-ene dominates, as Saytzeff (Zaitsev) predicts.', '{"a": "Hund''s rule concerns filling of degenerate orbitals.", "b": "The Hofmann rule favours the less substituted alkene, here pent-1-ene.", "c": "Hückel''s rule concerns aromaticity (4n+2 π electrons)."}'::jsonb, 'Saytzeff rule: the more substituted alkene is the major elimination product.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('7e086fd4-85fa-5ab8-ace7-83fb274caede', 'neet_ug', 'Chemistry', 'Alcohols, Phenols and Ethers', 'What is the IUPAC name of the organic compound formed in the following chemical reaction?
Acetone —(i) C₂H₅MgBr, dry ether; (ii) H₂O, H⁺→ Product', '[{"id": "a", "text": "Pentan-2-ol"}, {"id": "b", "text": "Pentan-3-ol"}, {"id": "c", "text": "2-methyl butan-2-ol"}, {"id": "d", "text": "2-methyl propan-2-ol"}]'::jsonb, 'c', 'The ethyl Grignard adds to acetone to give the tertiary alcohol (CH₃)₂C(OH)C₂H₅.', 'C₂H₅⁻ from the Grignard attacks the carbonyl carbon of (CH₃)₂C=O, and hydrolysis gives (CH₃)₂C(OH)CH₂CH₃. The longest chain has 4 C with OH and CH₃ both on C2, so the name is 2-methylbutan-2-ol. A ketone always gives a tertiary alcohol with RMgX.', '{"a": "A secondary alcohol; it would need an aldehyde.", "b": "A secondary alcohol, from propanal + C₂H₅MgBr.", "d": "From acetone + CH₃MgBr."}'::jsonb, 'RMgX with HCHO gives a 1° alcohol, with other aldehydes a 2° alcohol, and with ketones a 3° alcohol.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('446e315b-c4eb-557a-aa59-578d4dc09afb', 'neet_ug', 'Chemistry', 'Amines', 'Identify the compound that will react with Hinsberg''s reagent to give a solid which dissolves in alkali.', '[{"id": "a", "text": "CH₃CH₂–NH–CH₃"}, {"id": "b", "text": "CH₃CH₂–NH₂"}, {"id": "c", "text": "(CH₃CH₂)₂N–CH₃"}, {"id": "d", "text": "CH₃CH₂–NO₂"}]'::jsonb, 'b', 'A primary amine forms an N-alkylbenzenesulphonamide whose acidic N–H lets it dissolve in alkali.', 'Benzenesulphonyl chloride reacts with ethylamine to give C₆H₅SO₂NHC₂H₅. The N–H is made acidic by the strongly electron-withdrawing sulphonyl group, so the product dissolves in KOH. A secondary amine gives a sulphonamide with no N–H, which is insoluble in alkali, and a tertiary amine does not react.', '{"a": "Secondary amine: the sulphonamide is insoluble in alkali.", "c": "Tertiary amine: no reaction with Hinsberg''s reagent.", "d": "A nitroalkane, not an amine."}'::jsonb, 'Hinsberg test: 1° amine gives a product soluble in alkali, 2° gives an insoluble one, and 3° does not react.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('266ba05f-d221-59a1-bf33-3175bce5e4db', 'neet_ug', 'Chemistry', 'Biomolecules', 'The RBC deficiency is deficiency disease of:', '[{"id": "a", "text": "Vitamin B₆"}, {"id": "b", "text": "Vitamin B₁"}, {"id": "c", "text": "Vitamin B₂"}, {"id": "d", "text": "Vitamin B₁₂"}]'::jsonb, 'd', 'Vitamin B₁₂ deficiency causes pernicious anaemia, a deficiency of RBCs.', 'Cyanocobalamin (B₁₂) is needed for DNA synthesis in maturing erythrocytes, and its lack causes pernicious anaemia. B₁ deficiency causes beriberi, B₂ causes cheilosis, and B₆ causes convulsions.', '{"a": "B₆ deficiency causes convulsions.", "b": "B₁ deficiency causes beriberi.", "c": "B₂ deficiency causes cheilosis and fissuring at the corners of the mouth."}'::jsonb, 'Vitamin B₁₂ deficiency leads to pernicious anaemia.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('33d54ec4-9f65-58b5-97bc-55e2d32b4e34', 'neet_ug', 'Chemistry', 'Classification of Elements and Periodicity in Properties', 'From the following pairs of ions which one is not an iso-electronic pair?', '[{"id": "a", "text": "Na⁺, Mg²⁺"}, {"id": "b", "text": "Mn²⁺, Fe³⁺"}, {"id": "c", "text": "Fe²⁺, Mn²⁺"}, {"id": "d", "text": "O²⁻, F⁻"}]'::jsonb, 'c', 'Fe²⁺ has 24 electrons and Mn²⁺ has 23, so they are not isoelectronic.', 'Count the electrons: Na⁺ = Mg²⁺ = 10; Mn²⁺ = 25 − 2 = 23 and Fe³⁺ = 26 − 3 = 23; O²⁻ = F⁻ = 10. Fe²⁺ = 26 − 2 = 24 differs from Mn²⁺ (23).', '{"a": "Both have 10 electrons.", "b": "Both have 23 electrons (3d⁵).", "d": "Both have 10 electrons."}'::jsonb, 'Isoelectronic species have the same number of electrons; within such a series, size decreases as nuclear charge increases.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('854921ad-226d-5457-9bda-a8756c3ad108', 'neet_ug', 'Chemistry', 'Chemical Bonding and Molecular Structure', 'Which of the following molecules is non-polar in nature?', '[{"id": "a", "text": "CH₂O"}, {"id": "b", "text": "SbCl₅"}, {"id": "c", "text": "NO₂"}, {"id": "d", "text": "POCl₃"}]'::jsonb, 'b', 'SbCl₅ is symmetric trigonal bipyramidal, so its bond dipoles cancel.', 'SbCl₅ (sp³d, no lone pair) is trigonal bipyramidal and the vector sum of its Sb–Cl dipoles is zero. HCHO is trigonal planar with a polar C=O, NO₂ is bent, and POCl₃ is a distorted tetrahedron with different P=O and P–Cl dipoles, so all three are polar.', '{"a": "The C=O dipole is not cancelled.", "c": "Its bent shape leaves a net dipole.", "d": "P=O and P–Cl bonds are unequal, leaving a net dipole."}'::jsonb, 'Symmetric geometries with identical ligands (BF₃, CCl₄, PCl₅, SF₆) are non-polar.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('35c33645-7c1a-5865-81cd-a3093378c6bb', 'neet_ug', 'Chemistry', 'Thermodynamics', 'For irreversible expansion of an ideal gas under isothermal condition, the correct option is:', '[{"id": "a", "text": "ΔU ≠ 0, ΔS_total ≠ 0"}, {"id": "b", "text": "ΔU = 0, ΔS_total ≠ 0"}, {"id": "c", "text": "ΔU ≠ 0, ΔS_total = 0"}, {"id": "d", "text": "ΔU = 0, ΔS_total = 0"}]'::jsonb, 'b', 'For an ideal gas at constant T, ΔU = 0; an irreversible process gives ΔS_total > 0.', 'The internal energy of an ideal gas depends only on temperature, so ΔU = 0 in any isothermal process. For an irreversible (spontaneous) process the total entropy of system plus surroundings increases, so ΔS_total ≠ 0. ΔS_total = 0 holds only for a reversible path.', '{"a": "ΔU is zero for an isothermal ideal gas.", "c": "Both parts are wrong.", "d": "ΔS_total = 0 only for a reversible process."}'::jsonb, 'Ideal gas: U = f(T) only; for an irreversible process ΔS_universe > 0.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('65e55a46-c2f7-57e5-84ce-7b83d2411799', 'neet_ug', 'Chemistry', 'Solutions', 'The correct option for the value of vapour pressure of a solution at 45°C with benzene to octane in molar ratio 3 : 2 is:
[At 45°C vapour pressure of benzene is 280 mm Hg and that of octane is 420 mm Hg. Assume Ideal gas]', '[{"id": "a", "text": "168 mm of Hg"}, {"id": "b", "text": "336 mm of Hg"}, {"id": "c", "text": "350 mm of Hg"}, {"id": "d", "text": "160 mm of Hg"}]'::jsonb, 'b', 'Raoult''s law: P = 0.6×280 + 0.4×420 = 336 mm Hg.', 'The mole fractions are x(benzene) = 3/5 = 0.6 and x(octane) = 0.4. For an ideal solution P = x₁P₁° + x₂P₂° = 0.6(280) + 0.4(420) = 168 + 168 = 336 mm Hg.', '{"a": "This is only one component''s partial pressure.", "c": "This is the simple average of the two pure pressures.", "d": "Arithmetic error."}'::jsonb, 'Raoult''s law: P_total = Σ xᵢPᵢ° for an ideal solution.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('8da21e08-ba4d-5e55-a373-5adea3f979c5', 'neet_ug', 'Chemistry', 'Electrochemistry', 'The molar conductivity of 0.007 M acetic acid is 20 S cm² mol⁻¹. What is the dissociation constant of acetic acid? Choose the correct option.
[Λ°(H⁺) = 350 S cm² mol⁻¹, Λ°(CH₃COO⁻) = 50 S cm² mol⁻¹]', '[{"id": "a", "text": "2.50 × 10⁻⁴ mol L⁻¹"}, {"id": "b", "text": "1.75 × 10⁻⁵ mol L⁻¹"}, {"id": "c", "text": "2.50 × 10⁻⁵ mol L⁻¹"}, {"id": "d", "text": "1.75 × 10⁻⁴ mol L⁻¹"}]'::jsonb, 'b', 'α = 20/400 = 0.05, so Ka ≈ cα² = 0.007 × 0.0025 = 1.75 × 10⁻⁵.', 'Λ°(CH₃COOH) = 350 + 50 = 400 S cm² mol⁻¹, and α = Λm/Λ° = 20/400 = 0.05. Then Ka = cα²/(1 − α) ≈ cα² = 0.007 × (0.05)² = 1.75 × 10⁻⁵ mol L⁻¹.', '{"a": "Arithmetic or power-of-ten error.", "c": "Uses cα² wrongly.", "d": "Off by a factor of 10."}'::jsonb, 'Ostwald dilution law: Ka = cα²/(1 − α), with α = Λm/Λ°m.', 'med', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('0f8e96be-dac0-50e9-9d06-6a8b4fc6ac46', 'neet_ug', 'Chemistry', 'Chemical Kinetics', 'The slope of Arrhenius Plot (ln K v/s 1/T) of first order reaction is –5 × 10³ K. The value of Ea of the reaction is. Choose the correct option for your answer.
[Given R = 8.314 JK⁻¹ mol⁻¹]', '[{"id": "a", "text": "83.0 kJ mol⁻¹"}, {"id": "b", "text": "166 kJ mol⁻¹"}, {"id": "c", "text": "–83 kJ mol⁻¹"}, {"id": "d", "text": "41.5 kJ mol⁻¹"}]'::jsonb, 'd', 'The slope is −Ea/R, so Ea = 5000 × 8.314 J ≈ 41.5 kJ mol⁻¹.', 'ln k = ln A − Ea/(RT), so a plot of ln k against 1/T has slope −Ea/R. Therefore Ea = 5 × 10³ × 8.314 = 41 570 J mol⁻¹ ≈ 41.5 kJ mol⁻¹.', '{"a": "Doubled, as if the plot were log₁₀ with a wrong factor.", "b": "Quadrupled error.", "c": "Ea cannot be negative here."}'::jsonb, 'Arrhenius plot: slope of ln k vs 1/T = −Ea/R; slope of log k vs 1/T = −Ea/2.303R.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('2c15d466-b215-58d8-8aaa-60f66b47bb3b', 'neet_ug', 'Chemistry', 'The p-Block Elements', 'In which one of the following arrangements the given sequence is not strictly according to the properties indicated against it?', '[{"id": "a", "text": "H₂O < H₂S < H₂Se < H₂Te : Increasing pKa values"}, {"id": "b", "text": "NH₃ < PH₃ < AsH₃ < SbH₃ : Increasing acidic character"}, {"id": "c", "text": "CO₂ < SiO₂ < SnO₂ < PbO₂ : Increasing oxidizing power"}, {"id": "d", "text": "HF < HCl < HBr < HI : Increasing acidic strength"}]'::jsonb, 'a', 'Acidity rises from H₂O to H₂Te, so pKa decreases, not increases.', 'Down group 16 the H–E bond weakens, so H₂Te is the strongest acid and has the smallest pKa. The given order is therefore one of decreasing pKa, not increasing. Acidic character of group-15 hydrides increases down the group, PbO₂ is the strongest oxidiser because of the inert pair effect, and HI is the strongest hydrohalic acid.', '{"b": "Correct trend: acidic character increases down group 15.", "c": "Correct trend: the +4 state becomes less stable down group 14.", "d": "Correct trend: bond enthalpy decreases down the group."}'::jsonb, 'Group 16 hydride acidity: H₂O < H₂S < H₂Se < H₂Te.', 'med', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('f83ae937-3f5e-5542-9e06-1e5f1d2eed13', 'neet_ug', 'Chemistry', 'Coordination Compounds', 'Match List-I with List-II.
List-I | List-II
(A) [Fe(CN)₆]³⁻ | (i) 5.92 BM
(B) [Fe(H₂O)₆]³⁺ | (ii) 0 BM
(C) [Fe(CN)₆]⁴⁻ | (iii) 4.90 BM
(D) [Fe(H₂O)₆]²⁺ | (iv) 1.73 BM
Choose the correct answer from the options given below.', '[{"id": "a", "text": "A-ii, B-iv, C-iii, D-i"}, {"id": "b", "text": "A-i, B-iii, C-iv, D-ii"}, {"id": "c", "text": "A-iv, B-i, C-ii, D-iii"}, {"id": "d", "text": "A-iv, B-ii, C-i, D-iii"}]'::jsonb, 'c', 'With strong-field CN⁻ the complexes are low spin (n = 1 and n = 0); with weak-field H₂O they are high spin (n = 5 and n = 4).', 'In [Fe(CN)₆]³⁻, Fe³⁺ d⁵ low spin has 1 unpaired electron, giving 1.73 BM. In [Fe(H₂O)₆]³⁺, d⁵ high spin has 5, giving 5.92 BM. In [Fe(CN)₆]⁴⁻, Fe²⁺ d⁶ low spin has 0, giving 0 BM. In [Fe(H₂O)₆]²⁺, d⁶ high spin has 4, giving √24 = 4.90 BM.', '{"a": "Swaps the cyanide complexes'' moments.", "b": "Treats all four as high spin, or mismatches them.", "d": "Gives the aqua Fe³⁺ complex 0 BM, which is impossible for d⁵."}'::jsonb, 'μ = √[n(n+2)] BM; CN⁻ is a strong-field ligand and H₂O a weak-field ligand for Fe.', 'med', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('e2af47d1-2c67-52b8-a792-c60794d57abc', 'neet_ug', 'Chemistry', 'Alcohols, Phenols and Ethers', 'The product formed in the following chemical reaction is:
[Ketone–ester compound] —NaBH₄ / C₂H₅OH→ ? (structures in figure)', '[{"id": "a", "text": "Option (1) in figure"}, {"id": "b", "text": "Option (2) in figure"}, {"id": "c", "text": "Option (3) in figure"}, {"id": "d", "text": "Option (4) in figure"}]'::jsonb, 'c', 'NaBH₄ reduces the ketone C=O to CH–OH but leaves the ester untouched.', 'NaBH₄ is a mild hydride donor that reduces aldehydes and ketones to alcohols but does not normally reduce esters. So the ring ketone becomes a secondary alcohol while –CH₂COOCH₃ stays intact, which is option (c). Reducing the ester to –CH₂CH₂OH would need LiAlH₄.', '{"a": "Shows the ester reduced and the ketone retained, the opposite selectivity.", "b": "Shows the ester converted into a methyl carbinol, which is not possible with NaBH₄.", "d": "A hemiacetal-like structure that is not a stable reduction product."}'::jsonb, 'NaBH₄ reduces only C=O of aldehydes and ketones; LiAlH₄ also reduces esters and acids.', 'med', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', '/pyq/ug/2021/1846.webp'),
('07c69f6b-9c1c-512a-84c1-7aa5d26c9ae9', 'neet_ug', 'Chemistry', 'Aldehydes, Ketones and Carboxylic Acids', 'The intermediate compound ''X'' in the following chemical reaction is:
C₆H₅CH₃ + CrO₂Cl₂ —CS₂→ X —H₃O⁺→ C₆H₅CHO', '[{"id": "a", "text": "C₆H₅CH(OCOCH₃)₂"}, {"id": "b", "text": "C₆H₅CHCl₂"}, {"id": "c", "text": "C₆H₅CH₂Cl"}, {"id": "d", "text": "C₆H₅CH(OCrOHCl₂)₂"}]'::jsonb, 'd', 'In the Étard reaction, chromyl chloride forms a chromium complex C₆H₅CH(OCrOHCl₂)₂, which is hydrolysed to benzaldehyde.', 'Toluene treated with CrO₂Cl₂ in CS₂ gives a brown chromium complex (the Étard complex), C₆H₅CH(OCrOHCl₂)₂. Acid hydrolysis converts it to benzaldehyde without further oxidation to benzoic acid. The benzylidene diacetate intermediate belongs to the CrO₃/acetic anhydride route.', '{"a": "This is the intermediate with CrO₃ + (CH₃CO)₂O, not CrO₂Cl₂.", "b": "Formed by side-chain chlorination (Cl₂/hν), not by chromyl chloride.", "c": "Benzyl chloride is a monochlorination product and is not involved."}'::jsonb, 'Étard reaction: toluene + CrO₂Cl₂/CS₂, then H₃O⁺, gives benzaldehyde.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('3178a9b0-7f99-5ce0-85e1-ea38e79c3665', 'neet_ug', 'Chemistry', 'Aldehydes, Ketones and Carboxylic Acids', 'CH₃CH₂COO⁻Na⁺ —NaOH, +? / Heat→ CH₃CH₃ + Na₂CO₃.
Consider the above reaction and identify the missing reagent/chemical.', '[{"id": "a", "text": "Red Phosphorus"}, {"id": "b", "text": "CaO"}, {"id": "c", "text": "DIBAL-H"}, {"id": "d", "text": "B₂H₆"}]'::jsonb, 'b', 'Decarboxylation uses soda-lime (NaOH + CaO).', 'Heating a sodium carboxylate with soda-lime removes CO₂ as Na₂CO₃, giving an alkane with one carbon fewer. Sodium propanoate therefore gives ethane. CaO keeps the NaOH dry and non-fusing.', '{"a": "Red P is used in HVZ (with X₂) or HI reduction.", "c": "DIBAL-H reduces esters or nitriles to aldehydes.", "d": "Diborane is for hydroboration or reducing acids to alcohols."}'::jsonb, 'Soda-lime decarboxylation: RCOONa → RH (one carbon fewer).', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('a8043076-0342-527c-829f-23bf2484b788', 'neet_ug', 'Chemistry', 'Aldehydes, Ketones and Carboxylic Acids', 'Match List-I with List-II.
List-I | List-II
(A) C₆H₆ —CO, HCl / Anhyd. AlCl₃/CuCl→ | (i) Hell-Volhard-Zelinsky reaction
(B) R–CO–CH₃ + NaOX → | (ii) Gattermann-Koch reaction
(C) R–CH₂–OH + R''COOH —Conc. H₂SO₄→ | (iii) Haloform reaction
(D) R–CH₂COOH —(i) X₂/Red P, (ii) H₂O→ | (iv) Esterification
Choose the correct answer from the options given below.', '[{"id": "a", "text": "A-iii, B-ii, C-i, D-iv"}, {"id": "b", "text": "A-i, B-iv, C-iii, D-ii"}, {"id": "c", "text": "A-ii, B-iii, C-iv, D-i"}, {"id": "d", "text": "A-iv, B-i, C-ii, D-iii"}]'::jsonb, 'c', 'Gattermann–Koch, haloform, esterification, HVZ.', 'Benzene with CO/HCl over AlCl₃/CuCl is formylated to benzaldehyde (Gattermann–Koch). A methyl ketone with hypohalite gives a haloform (haloform reaction). An alcohol plus a carboxylic acid with conc. H₂SO₄ gives an ester. X₂/red P α-halogenates the acid (HVZ).', '{"a": "Mismatches A and B.", "b": "Mismatches all four.", "d": "Mismatches all four."}'::jsonb, 'HVZ needs an α-H in the carboxylic acid; the haloform reaction needs a CH₃CO– group.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('720c1d53-351e-54fa-b48d-72d174d0e9c4', 'neet_ug', 'Chemistry', 'Amines', 'The reagent ''R'' in the given sequence of chemical reaction is:
2,4,6-tribromoaniline —NaNO₂, HCl / 0–5°C→ 2,4,6-tribromobenzenediazonium chloride —R→ 1,3,5-tribromobenzene', '[{"id": "a", "text": "CH₃CH₂OH"}, {"id": "b", "text": "HI"}, {"id": "c", "text": "CuCN/KCN"}, {"id": "d", "text": "H₂O"}]'::jsonb, 'a', 'Ethanol (or H₃PO₂) replaces –N₂⁺ by –H.', 'Converting the diazonium salt to 1,3,5-tribromobenzene needs the N₂⁺ group replaced by hydrogen. Mild reducing agents such as ethanol (which is oxidised to ethanal) or hypophosphorous acid do this. This route makes 1,3,5-tribromobenzene, which direct bromination cannot give.', '{"b": "KI/HI gives an aryl iodide.", "c": "CuCN/KCN gives an aryl nitrile (Sandmeyer).", "d": "Warm water gives a phenol."}'::jsonb, 'ArN₂⁺ with H₃PO₂ or CH₃CH₂OH gives ArH (deamination).', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('18316c4f-f2cb-50d5-a931-8cfd63dc9899', 'neet_ug', 'Physics', 'Units and Measurements', 'If E and G respectively denote energy and gravitational constant, then E/G has the dimensions of:', '[{"id": "a", "text": "[M][L⁻¹][T⁻¹]"}, {"id": "b", "text": "[M][L⁰][T⁰]"}, {"id": "c", "text": "[M²][L⁻²][T⁻¹]"}, {"id": "d", "text": "[M²][L⁻¹][T⁰]"}]'::jsonb, 'd', '[ML²T⁻²]/[M⁻¹L³T⁻²] = [M²L⁻¹T⁰].', 'Energy is [ML²T⁻²]. From F = Gm²/r², G = [M⁻¹L³T⁻²]. Dividing gives [M^(1+1) L^(2−3) T^(−2+2)] = [M²L⁻¹T⁰].', '{"a": "Wrong powers of L and T.", "b": "Ignores the M⁻¹ in G.", "c": "Wrong L and T exponents."}'::jsonb, '[G] = M⁻¹L³T⁻².', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('dc5b0b48-7a9c-52af-99cc-68db0ae5cf6d', 'neet_ug', 'Physics', 'Units and Measurements', 'A screw gauge gives the following readings when used to measure the diameter of a wire
Main scale reading : 0 mm
Circular scale reading : 52 divisions
Given that 1 mm on main scale corresponds to 100 divisions on the circular scale. The diameter of the wire from the above data is:', '[{"id": "a", "text": "0.026 cm"}, {"id": "b", "text": "0.26 cm"}, {"id": "c", "text": "0.052 cm"}, {"id": "d", "text": "0.52 cm"}]'::jsonb, 'c', 'LC = 0.01 mm, so d = 52 × 0.01 = 0.52 mm = 0.052 cm.', 'The least count is 1 mm/100 = 0.01 mm. Diameter = MSR + CSR × LC = 0 + 52 × 0.01 = 0.52 mm = 0.052 cm.', '{"a": "Halves the value, as if the pitch were 0.5 mm.", "b": "Unit and factor error.", "d": "Gives 0.52 mm but labels it in cm."}'::jsonb, 'Screw gauge reading = MSR + (CSR × least count).', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('edbcb7db-6d4c-54c6-b279-d0d9ebea2d23', 'neet_ug', 'Physics', 'Units and Measurements', 'If force [F], acceleration [A] and time [T] are chosen as the fundamental physical quantities. Find the dimensions of energy.', '[{"id": "a", "text": "[F] [A] [T²]"}, {"id": "b", "text": "[F] [A] [T⁻¹]"}, {"id": "c", "text": "[F] [A⁻¹] [T]"}, {"id": "d", "text": "[F] [A] [T]"}]'::jsonb, 'a', 'E = F × distance, and distance ~ A T², so E = [F A T²].', 'Energy = force × displacement, and from s = ½at² displacement has dimensions [A T²]. Hence E = [F][A][T²]. Check: MLT⁻² · LT⁻² · T² = ML²T⁻².', '{"b": "The T power gives the wrong dimensions.", "c": "Is not ML²T⁻².", "d": "Gives ML²T⁻³, which is power."}'::jsonb, 'Express length in terms of the new base quantities using kinematics (L = AT²).', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('e9011f3c-9ea4-516e-ad40-d102889b5f6d', 'neet_ug', 'Physics', 'Laws of Motion', 'A small block slides down on a smooth inclined plane, starting from rest at time t = 0. Let Sₙ be the distance travelled by the block in the interval t = n – 1 to t = n. Then, the ratio Sₙ/Sₙ₊₁ is:', '[{"id": "a", "text": "(2n − 1)/(2n + 1)"}, {"id": "b", "text": "(2n + 1)/(2n − 1)"}, {"id": "c", "text": "2n/(2n − 1)"}, {"id": "d", "text": "(2n − 1)/2n"}]'::jsonb, 'a', 'Distance in the nth second ∝ (2n − 1), so the ratio is (2n − 1)/(2n + 1).', 'On a smooth incline the acceleration a = g sin θ is constant and u = 0. Distance in the nth second is Sₙ = (a/2)(2n − 1), and similarly Sₙ₊₁ = (a/2)(2n + 1). Their ratio is (2n − 1)/(2n + 1).', '{"b": "This is the inverted ratio.", "c": "Wrong expression for the nth-second distance.", "d": "Wrong expression for the nth-second distance."}'::jsonb, 'From rest under uniform acceleration, successive equal intervals cover distances in the ratio 1 : 3 : 5 : …', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('ddc42b56-fd2a-58ab-bef1-22413915ee30', 'neet_ug', 'Physics', 'Work, Energy and Power', 'Water falls from a height of 60 m at the rate of 15 kg/s to operate a turbine. The losses due to frictional force are 10% of the input energy. How much power is generated by the turbine? (g = 10 m/s²)', '[{"id": "a", "text": "8.1 kW"}, {"id": "b", "text": "12.3 kW"}, {"id": "c", "text": "7.0 kW"}, {"id": "d", "text": "10.2 kW"}]'::jsonb, 'a', 'Input = 15 × 10 × 60 = 9 kW; 90% of it is 8.1 kW.', 'Input power = (dm/dt)gh = 15 × 10 × 60 = 9000 W. With 10% lost to friction, output = 0.9 × 9000 = 8100 W = 8.1 kW.', '{"b": "Arithmetic error.", "c": "Takes a larger loss than 10%.", "d": "Adds the loss instead of subtracting it."}'::jsonb, 'Hydroelectric power: P = η ṁ g h.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('74f55b37-6c12-5fdb-af39-20c0c5ffeb05', 'neet_ug', 'Physics', 'Gravitation', 'A particle is released from height S from the surface of the Earth. At a certain height its kinetic energy is three times its potential energy. The height from the surface of earth and the speed of the particle at that instant are respectively:', '[{"id": "a", "text": "S/4, √(3gS)/2"}, {"id": "b", "text": "S/2, √(3gS)/2"}, {"id": "c", "text": "S/4, √(3gS/2)"}, {"id": "d", "text": "S/4, 3gS/2"}]'::jsonb, 'c', 'mgS = mgh + 3mgh gives h = S/4 and v² = 2g(3S/4) = 3gS/2.', 'Energy conservation with PE measured from the surface: mgS = PE + KE = 4mgh, so h = S/4. The fall so far is 3S/4, so v = √(2g·3S/4) = √(3gS/2).', '{"a": "Gives speed √(3gS)/2 = √(3gS/4), which is too small.", "b": "Wrong height.", "d": "This is v², not v."}'::jsonb, 'Free fall from height H: when KE = n × PE, h = H/(n+1).', 'med', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('4651f5fd-8764-53b9-9c4d-7f545ae905a6', 'neet_ug', 'Physics', 'Gravitation', 'The escape velocity from the Earth''s surface is v. The escape velocity from the surface of another planet having a radius, four times that of Earth and same mass density is:', '[{"id": "a", "text": "2v"}, {"id": "b", "text": "3v"}, {"id": "c", "text": "4v"}, {"id": "d", "text": "v"}]'::jsonb, 'c', 'vₑ = √(2GM/R) ∝ R√ρ, so 4 times R gives 4v.', 'With M = (4/3)πR³ρ, vₑ = √(8πGρ/3)·R. At equal density vₑ ∝ R, so a radius four times larger gives an escape velocity of 4v.', '{"a": "Assumes vₑ ∝ √R.", "b": "No such scaling applies.", "d": "Ignores the radius dependence."}'::jsonb, 'vₑ = √(2gR) = R√(8πGρ/3).', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('c5d5ce2b-2479-5363-8189-4cffe07673ac', 'neet_ug', 'Physics', 'Mechanical Properties of Fluids', 'The velocity of a small ball of mass M and density d, when dropped in a container filled with glycerine becomes constant after some time. If the density of glycerine is d/2, then the viscous force acting on the ball will be:', '[{"id": "a", "text": "Mg"}, {"id": "b", "text": "(3/2)Mg"}, {"id": "c", "text": "2Mg"}, {"id": "d", "text": "Mg/2"}]'::jsonb, 'd', 'At terminal velocity, viscous force = Mg − buoyancy = Mg − Mg/2 = Mg/2.', 'Ball volume is V = M/d, so buoyancy = V(d/2)g = Mg/2. At terminal (constant) velocity the net force is zero: F_v + Mg/2 = Mg, so F_v = Mg/2.', '{"a": "Neglects buoyancy.", "b": "Adds buoyancy instead of subtracting it.", "c": "No physical basis."}'::jsonb, 'Terminal velocity: weight = buoyancy + viscous drag (Stokes).', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('be182b02-4591-50e1-bdc4-e6b688a24be9', 'neet_ug', 'Physics', 'Thermal Properties of Matter', 'A cup of coffee cools from 90°C to 80°C in t minutes, when the room temperature is 20°C. The time taken by a similar cup of coffee to cool from 80°C to 60°C at a room temperature same at 20°C is:', '[{"id": "a", "text": "(13/5)t"}, {"id": "b", "text": "(10/13)t"}, {"id": "c", "text": "(5/13)t"}, {"id": "d", "text": "(13/10)t"}]'::jsonb, 'a', 'Newton''s law (average form): 10/t = k(65) and 20/t'' = k(50), so t'' = 13t/5.', 'Using rate = k(T_avg − T₀): for 90→80, 10/t = k(85 − 20) = 65k, so k = 10/(65t). For 80→60, 20/t'' = k(70 − 20) = 50k, so t'' = 20/(50k) = 20 × 65t/500 = 13t/5.', '{"b": "Inverts the ratio and omits the factor of 2.", "c": "Inverted ratio.", "d": "Omits the doubled temperature drop."}'::jsonb, 'Newton''s law of cooling: (T₁ − T₂)/t = k[(T₁ + T₂)/2 − T₀].', 'med', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('4933bbd5-cdff-5cd6-bd88-4bfb4e81729d', 'neet_ug', 'Physics', 'Kinetic Theory', 'Match Column-I and Column-II and choose the correct match from the given choices.
Column-I | Column-II
(A) Root mean square speed of gas molecules | (P) (1/3)nmv̄²
(B) Pressure exerted by ideal gas | (Q) √(3RT/M)
(C) Average kinetic energy of a molecule | (R) (5/2)RT
(D) Total internal energy of 1 mole of a diatomic gas | (S) (3/2)k_BT', '[{"id": "a", "text": "(A) - (Q), (B) - (R), (C) - (S), (D) - (P)"}, {"id": "b", "text": "(A) - (Q), (B) - (P), (C) - (S), (D) - (R)"}, {"id": "c", "text": "(A) - (R), (B) - (Q), (C) - (P), (D) - (S)"}, {"id": "d", "text": "(A) - (R), (B) - (P), (C) - (S), (D) - (Q)"}]'::jsonb, 'b', 'v_rms = √(3RT/M), P = (1/3)nmv̄², KE per molecule = (3/2)k_BT, U per mole of diatomic gas = (5/2)RT.', 'The rms speed is √(3RT/M), so A–Q. Kinetic theory gives pressure P = (1/3)nmv̄², so B–P. The average translational KE of one molecule is (3/2)k_BT, so C–S. A diatomic molecule has 5 degrees of freedom, so one mole has U = (5/2)RT, giving D–R.', '{"a": "Pairs pressure with (5/2)RT and internal energy with the pressure formula.", "c": "Gives rms speed as (5/2)RT, which has the dimensions of energy, not speed.", "d": "Swaps rms speed with internal energy and internal energy with rms speed."}'::jsonb, 'Each degree of freedom carries (1/2)k_BT; a diatomic gas has f = 5, so Cv = (5/2)R.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('5f7972e1-3927-5042-a707-fa4ba621f23c', 'neet_ug', 'Physics', 'Oscillations', 'A body is executing simple harmonic motion with frequency ''n'', the frequency of its potential energy is:', '[{"id": "a", "text": "2n"}, {"id": "b", "text": "3n"}, {"id": "c", "text": "4n"}, {"id": "d", "text": "n"}]'::jsonb, 'a', 'PE ∝ x² ∝ sin²ωt, which oscillates at twice the frequency of the motion.', 'With x = A sin ωt, U = (1/2)kA² sin²ωt = (1/4)kA²(1 − cos 2ωt). The PE varies at angular frequency 2ω, so its frequency is 2n.', '{"b": "No cubic term appears in the energy expression.", "c": "That would need sin⁴ dependence.", "d": "That is the frequency of the displacement, not of the energy."}'::jsonb, 'In SHM, both KE and PE oscillate at twice the frequency of displacement; the total energy stays constant.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('a8cd8b61-cfb8-5c39-b8d2-7f25f2149780', 'neet_ug', 'Physics', 'Oscillations', 'A spring is stretched by 5 cm by a force 10 N. The time period of the oscillations when a mass of 2 kg is suspended by it is:', '[{"id": "a", "text": "6.28 s"}, {"id": "b", "text": "3.14 s"}, {"id": "c", "text": "0.628 s"}, {"id": "d", "text": "0.0628 s"}]'::jsonb, 'c', 'k = 10/0.05 = 200 N/m, so T = 2π√(2/200) = 0.628 s.', 'The spring constant is k = F/x = 10/0.05 = 200 N m⁻¹. Then T = 2π√(m/k) = 2π√(2/200) = 2π × 0.1 = 0.628 s.', '{"a": "Off by a factor of 10; it uses √(m/k) = 1 instead of 0.1.", "b": "This is π, which drops the factor 2 and the √0.01.", "d": "Off by a factor of 10 on the small side."}'::jsonb, 'Spring–mass time period: T = 2π√(m/k), independent of g.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('24bd623a-02e1-5080-81bf-46415a3bf5d1', 'neet_ug', 'Physics', 'Electrostatic Potential and Capacitance', 'Two charged spherical conductors of radius R₁ and R₂ are connected by a wire. Then the ratio of surface charge densities of the spheres (σ₁/σ₂) is:', '[{"id": "a", "text": "R₂/R₁"}, {"id": "b", "text": "√(R₁/R₂)"}, {"id": "c", "text": "R₁²/R₂²"}, {"id": "d", "text": "R₁/R₂"}]'::jsonb, 'a', 'Equal potentials give Q ∝ R, so σ = Q/4πR² ∝ 1/R.', 'Once connected, the spheres reach the same potential: kQ₁/R₁ = kQ₂/R₂, so Q₁/Q₂ = R₁/R₂. Then σ₁/σ₂ = (Q₁/R₁²)/(Q₂/R₂²) = R₂/R₁.', '{"b": "No square root comes into it.", "c": "Treats σ as increasing with R², which is the wrong way round.", "d": "This is the ratio of charges, not of charge densities."}'::jsonb, 'Charge density is greater at sharper (smaller radius) parts of a conductor, which is why charge leaks from sharp points.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('23f05846-6768-5a3f-9f79-c0478446fb0e', 'neet_ug', 'Physics', 'Electrostatic Potential and Capacitance', 'The equivalent capacitance of the combination shown in the figure is:', '[{"id": "a", "text": "2C"}, {"id": "b", "text": "C/2"}, {"id": "c", "text": "3C/2"}, {"id": "d", "text": "3C"}]'::jsonb, 'a', 'The middle capacitor has both plates joined to the same node, so it is shorted, leaving two C in parallel.', 'The top and bottom capacitors each join the left terminal to the right-hand wire. Both plates of the middle capacitor connect to wires that lead straight to the right terminal, so there is no potential difference across it and it stores no charge. The equivalent is C + C = 2C.', '{"b": "That would be two capacitors in series.", "c": "Wrongly treats the middle capacitor as active in a mixed combination.", "d": "Wrongly adds all three in parallel."}'::jsonb, 'A capacitor whose two plates are at the same potential (shorted) does not contribute to the equivalent capacitance.', 'med', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', '/pyq/ug/2021/2214.webp'),
('997e4109-fe26-5d47-b88c-72d7e1b270b4', 'neet_ug', 'Physics', 'Electrostatic Potential and Capacitance', 'A parallel plate capacitor has a uniform electric field ''E'' in the space between the plates. If the distance between the plates is ''d'' and the area of each plate is ''A'', the energy stored in the capacitor is:
(ε₀ = permittivity of free space)', '[{"id": "a", "text": "ε₀EAd"}, {"id": "b", "text": "(1/2)ε₀E²Ad"}, {"id": "c", "text": "E²Ad/ε₀"}, {"id": "d", "text": "(1/2)ε₀E²"}]'::jsonb, 'b', 'Energy = energy density (1/2)ε₀E² × volume Ad.', 'The energy density in the field is u = (1/2)ε₀E², and the field fills a volume Ad. So U = (1/2)ε₀E²Ad. Equivalently, (1/2)CV² = (1/2)(ε₀A/d)(Ed)² gives the same result.', '{"a": "Dimensionally wrong: it is linear in E and lacks the factor 1/2.", "c": "Puts ε₀ in the denominator, which is dimensionally wrong.", "d": "This is the energy density only, not the total energy."}'::jsonb, 'Energy density of an electric field: u = (1/2)ε₀E².', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('c12d2809-bd52-5cb0-957a-dc4a5d12e8da', 'neet_ug', 'Physics', 'Current Electricity', 'The effective resistance of a parallel connection that consists of four wires of equal length, equal area of cross-section and same material is 0.25 Ω. What will be the effective resistance if they are connected in series?', '[{"id": "a", "text": "0.5 Ω"}, {"id": "b", "text": "1 Ω"}, {"id": "c", "text": "4 Ω"}, {"id": "d", "text": "0.25 Ω"}]'::jsonb, 'c', 'R/4 = 0.25 Ω gives R = 1 Ω, so the series value is 4R = 4 Ω.', 'The four wires are identical, each of resistance R. In parallel, R/4 = 0.25 Ω, so R = 1 Ω. In series, 4R = 4 Ω.', '{"a": "That would be only two wires in series.", "b": "This is the resistance of a single wire.", "d": "This is the parallel value, which is unchanged."}'::jsonb, 'For n identical resistors, R_series/R_parallel = n².', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('a3c788de-ae79-524c-bc18-86d15883d20f', 'neet_ug', 'Physics', 'Current Electricity', 'Column-I gives certain physical terms associated with flow of current through a metallic conductor. Column-II gives some mathematical relations involving electrical quantities. Match Column-I and Column-II with appropriate relations.
Column-I | Column-II
(A) Drift Velocity | (P) m/(ne²ρ)
(B) Electrical Resistivity | (Q) nev_d
(C) Relaxation Period | (R) eEτ/m
(D) Current Density | (S) E/J', '[{"id": "a", "text": "(A) - (R), (B) - (S), (C) - (Q), (D) - (P)"}, {"id": "b", "text": "(A) - (R), (B) - (P), (C) - (S), (D) - (Q)"}, {"id": "c", "text": "(A) - (R), (B) - (Q), (C) - (S), (D) - (P)"}, {"id": "d", "text": "(A) - (R), (B) - (S), (C) - (P), (D) - (Q)"}]'::jsonb, 'd', 'v_d = eEτ/m, ρ = E/J, τ = m/(ne²ρ), J = nev_d.', 'Drift velocity is v_d = eEτ/m (A–R). From J = σE, resistivity ρ = E/J (B–S). Since ρ = m/(ne²τ), the relaxation time is τ = m/(ne²ρ) (C–P). Current density is J = nev_d (D–Q).', '{"a": "Matches relaxation time with nev_d, which is the current density.", "b": "Matches resistivity with m/(ne²ρ), which is τ.", "c": "Matches resistivity with current density."}'::jsonb, 'Resistivity of a metal: ρ = m/(ne²τ); it rises with temperature because τ falls.', 'med', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('0a8c90fe-c538-5533-a304-45429dab4109', 'neet_ug', 'Physics', 'Electric Charges and Fields', 'Polar molecules are the molecules:', '[{"id": "a", "text": "acquire a dipole moment only in the presence of electric field due to displacement of charges."}, {"id": "b", "text": "acquire a dipole moment only when magnetic field is absent."}, {"id": "c", "text": "having a permanent electric dipole moment."}, {"id": "d", "text": "having zero dipole moment."}]'::jsonb, 'c', 'In polar molecules such as H₂O, the centres of positive and negative charge do not coincide, so they have a permanent dipole moment.', 'A polar molecule has its centres of positive and negative charge separated even without an external field, so it carries a permanent dipole moment. Non-polar molecules acquire a dipole only when an external field is applied (induced dipole).', '{"a": "Describes non-polar molecules, which have induced dipoles.", "b": "A magnetic field has nothing to do with electric polarity.", "d": "Zero dipole moment describes non-polar molecules in the absence of a field."}'::jsonb, 'H₂O and HCl are polar; O₂, N₂ and CO₂ are non-polar.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('4902ec8f-2867-5bc0-ac34-2828d23651c4', 'neet_ug', 'Physics', 'Moving Charges and Magnetism', 'An infinitely long straight conductor carries a current of 5 A as shown. An electron is moving with a speed of 10⁵ m/s parallel to the conductor. The perpendicular distance between the electron and the conductor is 20 cm at an instant. Calculate the magnitude of the force experienced by the electron at that instant.', '[{"id": "a", "text": "8π × 10⁻²⁰ N"}, {"id": "b", "text": "4π × 10⁻²⁰ N"}, {"id": "c", "text": "8 × 10⁻²⁰ N"}, {"id": "d", "text": "4 × 10⁻²⁰ N"}]'::jsonb, 'c', 'B = μ₀I/2πr = 5 × 10⁻⁶ T, and F = evB = 8 × 10⁻²⁰ N.', 'At 0.2 m, B = μ₀I/(2πr) = (2 × 10⁻⁷ × 5)/0.2 = 5 × 10⁻⁶ T. The velocity is perpendicular to B, so F = evB = 1.6 × 10⁻¹⁹ × 10⁵ × 5 × 10⁻⁶ = 8 × 10⁻²⁰ N.', '{"a": "Keeps a stray π that cancels in μ₀/2π.", "b": "Keeps a stray π and also halves the result.", "d": "Half the correct value, from an error in B."}'::jsonb, 'Field of a long straight wire: B = μ₀I/(2πr), and μ₀/2π = 2 × 10⁻⁷ T m A⁻¹.', 'med', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', '/pyq/ug/2021/2320.webp'),
('688ab9a7-3f64-5bbe-acf8-7f1ac65aad68', 'neet_ug', 'Physics', 'Moving Charges and Magnetism', 'A thick current carrying cable of radius ''R'' carries current ''I'' uniformly distributed across its cross-section. The variation of magnetic field B(r) due to the cable with the distance ''r'' from the axis of the cable is represented by:', '[{"id": "a", "text": "Option (1) in figure"}, {"id": "b", "text": "Option (2) in figure"}, {"id": "c", "text": "Option (3) in figure"}, {"id": "d", "text": "Option (4) in figure"}]'::jsonb, 'b', 'B rises linearly inside (r < R) and falls as 1/r outside, peaking at the surface.', 'Ampere''s law inside gives B·2πr = μ₀I r²/R², so B = μ₀Ir/(2πR²) ∝ r. Outside, B = μ₀I/(2πr) ∝ 1/r. The graph rises linearly to a maximum at r = R and then decays hyperbolically, which is graph (2).', '{"a": "Shows B increasing linearly for all r, which ignores the 1/r fall outside.", "c": "Shows saturation, with no peak and no decay.", "d": "Shows a curve rising without limit."}'::jsonb, 'For a solid cylindrical conductor, B is zero on the axis and maximum at the surface.', 'med', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', '/pyq/ug/2021/2321.webp'),
('6869f858-b242-57ed-862b-e7d6664acb62', 'neet_ug', 'Physics', 'Alternating Current', 'A capacitor of capacitance ''C'', is connected across an ac source of voltage V, given by V = V₀ sin ωt
The displacement current between the plates of the capacitor, would then be given by:', '[{"id": "a", "text": "I_d = (V₀/ωC) cos ωt"}, {"id": "b", "text": "I_d = (V₀/ωC) sin ωt"}, {"id": "c", "text": "I_d = V₀ωC sin ωt"}, {"id": "d", "text": "I_d = V₀ωC cos ωt"}]'::jsonb, 'd', 'I_d = C dV/dt = V₀ωC cos ωt.', 'The displacement current equals the conduction current in the leads: I_d = ε₀ dΦ_E/dt = dq/dt = C dV/dt. Differentiating V₀ sin ωt gives I_d = V₀ωC cos ωt, which leads the voltage by π/2.', '{"a": "Divides by ωC instead of multiplying.", "b": "Divides by ωC and also has the wrong phase.", "c": "Has the right amplitude but is in phase with V instead of leading it."}'::jsonb, 'Displacement current I_d = ε₀ dΦ_E/dt; it keeps the current continuous across a capacitor gap.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('8f591c4d-539c-5c62-8270-85af378d2798', 'neet_ug', 'Physics', 'Electromagnetic Waves', 'For a plane electromagnetic wave propagating in x-direction, which one of the following combination gives the correct possible directions for electric field (E) and magnetic field (B) respectively?', '[{"id": "a", "text": "−ĵ + k̂, −ĵ − k̂"}, {"id": "b", "text": "ĵ + k̂, −ĵ − k̂"}, {"id": "c", "text": "−ĵ + k̂, −ĵ + k̂"}, {"id": "d", "text": "ĵ + k̂, ĵ + k̂"}]'::jsonb, 'a', 'E × B must point along +x, with E ⊥ B.', 'For (a), E·B = 1 − 1 = 0, and E × B = (−ĵ + k̂) × (−ĵ − k̂) = î + î = 2î, which is along +x. In (b), (c) and (d), E and B are parallel or antiparallel, so E × B = 0.', '{"b": "B is antiparallel to E, so E × B = 0.", "c": "E and B are identical, so E × B = 0.", "d": "E and B are identical, so E × B = 0."}'::jsonb, 'In an EM wave, E, B and the propagation direction are mutually perpendicular, with propagation along E × B.', 'med', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('5d139fa9-e2a7-52cf-8940-7069171a1bd3', 'neet_ug', 'Physics', 'Ray Optics and Optical Instruments', 'A lens of large focal length and large aperture is best suited as an objective of an astronomical telescope since:', '[{"id": "a", "text": "a large aperture contributes to the quality and visibility of the images."}, {"id": "b", "text": "a large area of the objective ensures better light gathering power."}, {"id": "c", "text": "a large aperture provides a better resolution."}, {"id": "d", "text": "all of the above."}]'::jsonb, 'd', 'A large aperture collects more light and resolves finer detail, giving brighter and clearer images.', 'Light gathering power ∝ D², so a large aperture shows faint objects. The limiting angle of resolution ≈ 1.22λ/D falls as D rises, so resolution improves. Together these improve image quality and visibility. A large focal length also raises the magnification f_o/f_e. All three statements are therefore correct.', '{"a": "True, but only one of the reasons.", "b": "True, but only one of the reasons.", "c": "True, but only one of the reasons."}'::jsonb, 'Telescope magnification is f_o/f_e; resolving power ∝ D/λ.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('c26b5c9c-abf2-5ad5-8789-f7565e4186b1', 'neet_ug', 'Physics', 'Dual Nature of Radiation and Matter', 'The number of photons per second on an average emitted by the source of monochromatic light of wavelength 600 nm, when it delivers the power of 3.3 × 10⁻³ watt will be: (h = 6.6 × 10⁻³⁴ Js)', '[{"id": "a", "text": "10¹⁷"}, {"id": "b", "text": "10¹⁶"}, {"id": "c", "text": "10¹⁵"}, {"id": "d", "text": "10¹⁸"}]'::jsonb, 'b', 'E_photon = hc/λ = 3.3 × 10⁻¹⁹ J, so N = P/E = 10¹⁶ s⁻¹.', 'Each photon carries hc/λ = (6.6 × 10⁻³⁴ × 3 × 10⁸)/(6 × 10⁻⁷) = 3.3 × 10⁻¹⁹ J. The photon rate is P/E = 3.3 × 10⁻³ / 3.3 × 10⁻¹⁹ = 10¹⁶ per second.', '{"a": "Off by a factor of 10.", "c": "Off by a factor of 10.", "d": "Off by a factor of 100."}'::jsonb, 'Photon flux N = Pλ/(hc).', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('36c0637d-b64b-5f59-96c2-030a5bdf3aba', 'neet_ug', 'Physics', 'Ray Optics and Optical Instruments', 'A convex lens ''A'' of focal length 20 cm and a concave lens ''B'' of focal length 5 cm are kept along the same axis with a distance ''d'' between them. If a parallel beam of light falling on ''A'' leaves ''B'' as a parallel beam, then the distance ''d'' in cm will be:', '[{"id": "a", "text": "15"}, {"id": "b", "text": "50"}, {"id": "c", "text": "30"}, {"id": "d", "text": "25"}]'::jsonb, 'a', 'The foci must coincide: d = f_A − |f_B| = 20 − 5 = 15 cm.', 'Lens A converges parallel light towards its focus 20 cm away. For B to make it parallel again, that point must be B''s focal point, which lies 5 cm beyond B (a virtual object for the concave lens). So d = 20 − 5 = 15 cm. Check: the combination power 1/20 − 1/5 + d/(20 × 5) = 0 gives d = 15.', '{"b": "Not a sum or difference of the focal lengths.", "c": "Arbitrary value.", "d": "Adds the focal lengths, which applies only to two convex lenses."}'::jsonb, 'A system is afocal (telescopic) when the second focal point of the first lens coincides with the first focal point of the second lens.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('b5f66571-cce5-5af7-ae04-ef8929cb3b0f', 'neet_ug', 'Physics', 'Ray Optics and Optical Instruments', 'Find the value of the angle of emergence from the prism. Refractive index of the glass is √3.', '[{"id": "a", "text": "30°"}, {"id": "b", "text": "45°"}, {"id": "c", "text": "90°"}, {"id": "d", "text": "60°"}]'::jsonb, 'd', 'Normal entry, then incidence of 30° at the vertical face: sin e = √3 sin 30° gives e = 60°.', 'The ray enters the hypotenuse normally without deviation. The angle between the hypotenuse and the vertical face is 30° (the angles of the triangle are 90°, 60° and 30°), so the ray meets the vertical face at an angle of incidence of 30°. The critical angle is sin⁻¹(1/√3) ≈ 35°, so there is no TIR. Then sin e = √3 × 1/2, so e = 60°.', '{"a": "This is the internal angle of incidence, not the emergent angle.", "b": "Would need μ = √2.", "c": "Grazing emergence would need incidence exactly at the critical angle."}'::jsonb, 'At the second face of a prism, r₂ = A − r₁; for normal incidence r₁ = 0, so r₂ = A.', 'med', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', '/pyq/ug/2021/2328.webp'),
('837e4060-4b0a-508c-bc6f-1e63d17b170e', 'neet_ug', 'Physics', 'Electric Charges and Fields', 'A dipole is placed in an electric field as shown. In which direction will it move?', '[{"id": "a", "text": "towards the right as its potential energy will decrease."}, {"id": "b", "text": "towards the left as its potential energy will decrease."}, {"id": "c", "text": "towards the right as its potential energy will increase."}, {"id": "d", "text": "towards the left as its potential energy will increase."}]'::jsonb, 'a', 'The field weakens to the right (lines diverge), so the force on +q (in the stronger field) wins and the dipole moves right while U falls.', 'The lines diverge to the right, so E is stronger on the left. +q sits on the left in the stronger field and is pushed right. −q sits in the weaker field and is pushed left with a smaller force, so the net force is to the right. The dipole is antiparallel to E (p points from −q to +q), so U = −p·E = +pE, and U falls as it moves into the weaker field. A system moves spontaneously towards lower potential energy.', '{"b": "The net force points right, not left.", "c": "Motion under conservative forces lowers potential energy.", "d": "Both the direction and the energy change are wrong."}'::jsonb, 'A dipole in a uniform field feels only a torque; in a non-uniform field it also feels a net force.', 'hard', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', '/pyq/ug/2021/2429.webp'),
('b219bba8-d9cf-5b9f-8498-fbc6495da6d8', 'neet_ug', 'Physics', 'Dual Nature of Radiation and Matter', 'An electromagnetic wave of wavelength ''λ'' is incident on a photosensitive surface of negligible work function. If ''m'' mass is of photoelectron emitted from the surface has de-Broglie wavelength λ_d, then:', '[{"id": "a", "text": "λ_d = (2mc/h)λ²"}, {"id": "b", "text": "λ = (2mc/h)λ_d²"}, {"id": "c", "text": "λ = (2h/mc)λ_d²"}, {"id": "d", "text": "λ = (2m/hc)λ_d²"}]'::jsonb, 'b', 'hc/λ = p²/2m = h²/(2mλ_d²), so λ = (2mc/h)λ_d².', 'With φ = 0, all the photon energy becomes kinetic energy: hc/λ = p²/(2m), and p = h/λ_d. So hc/λ = h²/(2mλ_d²), which gives λ = 2mcλ_d²/h.', '{"a": "Swaps λ and λ_d.", "c": "Inverts the constant factor.", "d": "Dimensionally inconsistent."}'::jsonb, 'de Broglie wavelength of a particle with kinetic energy K: λ = h/√(2mK).', 'med', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('df0589db-5a62-5bf6-a089-6a7e0db0427f', 'neet_ug', 'Physics', 'Nuclei', 'A nucleus with mass number 240 breaks into two fragments each of mass number 120, the binding energy per nucleon of unfragmented nuclei is 7.6 MeV while that of fragments is 8.5 MeV. The total gain in the Binding Energy in the process is:', '[{"id": "a", "text": "9.4 MeV"}, {"id": "b", "text": "804 MeV"}, {"id": "c", "text": "216 MeV"}, {"id": "d", "text": "0.9 MeV"}]'::jsonb, 'c', 'ΔBE = 240 × (8.5 − 7.6) = 216 MeV.', 'The initial BE is 240 × 7.6 = 1824 MeV and the final BE is 2 × 120 × 8.5 = 2040 MeV. The gain is 2040 − 1824 = 216 MeV, which is released in fission.', '{"a": "Not a meaningful combination of the data.", "b": "Arithmetic error.", "d": "This is the gain per nucleon only."}'::jsonb, 'Fission of heavy nuclei releases energy because BE per nucleon rises towards the peak near A ≈ 56.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('21a29a5e-389d-5d15-967d-f7d8e234f9d8', 'neet_ug', 'Physics', 'Semiconductor Electronics: Materials, Devices and Simple Circuits', 'The electron concentration in an n-type semiconductor is the same as hole concentration in a p-type semiconductor. An external field (electric) is applied across each of them. Compare the currents in them.', '[{"id": "a", "text": "current in p-type > current in n-type."}, {"id": "b", "text": "current in n-type > current in p-type."}, {"id": "c", "text": "No current will flow in p-type, current will only flow in n-type."}, {"id": "d", "text": "current in n-type = current in p-type."}]'::jsonb, 'b', 'Electrons are more mobile than holes, so at equal carrier density the n-type current is larger.', 'Current I = neAv_d = neAμE. The carrier densities are equal, but electron mobility μ_e is greater than hole mobility μ_h, so the n-type sample carries more current under the same field.', '{"a": "Holes have lower mobility, not higher.", "c": "Holes do conduct in p-type material.", "d": "Ignores the difference in mobilities."}'::jsonb, 'Mobility μ = v_d/E; in Si, μ_e is about 3 times μ_h.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('81fde954-795b-5535-9e78-f9f67ebd99e2', 'neet_ug', 'Physics', 'Semiconductor Electronics: Materials, Devices and Simple Circuits', 'Consider the following statements (A) and (B) and identify the correct answer.
(A) A zener diode is connected in reverse bias, when used as a voltage regulator.
(B) The potential barrier of p-n junction lies between 0.1 V to 0.3 V.', '[{"id": "a", "text": "(A) and (B) both are incorrect."}, {"id": "b", "text": "(A) is correct and (B) is incorrect."}, {"id": "c", "text": "(A) is incorrect but (B) is correct."}, {"id": "d", "text": "(A) and (B) both are correct."}]'::jsonb, 'b', 'A Zener diode regulates in reverse breakdown; the barrier is about 0.7 V for Si (0.3 V for Ge), not 0.1–0.3 V.', 'A Zener diode is operated in reverse bias at breakdown, where its voltage stays nearly constant, so (A) is true. A p-n junction barrier is typically about 0.7 V for Si and about 0.3 V for Ge. The general range 0.1–0.3 V is not correct, so (B) is false.', '{"a": "(A) is a true statement.", "c": "A Zener diode is reverse biased for regulation, and (B) is wrong.", "d": "(B) understates the barrier for silicon."}'::jsonb, 'Zener regulator: reverse biased, with a series resistor absorbing the excess voltage.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('59cb2fe7-e2e7-5412-a584-356419565574', 'neet_ug', 'Physics', 'Motion in a Plane', 'A particle moving in a circle of radius R with a uniform speed takes a time T to complete one revolution.
If this particle were projected with the same speed at an angle ''θ'' to the horizontal, the maximum height attained by it equals 4R. The angle of projection, θ, is then given by:', '[{"id": "a", "text": "θ = cos⁻¹(π²R/gT²)^½"}, {"id": "b", "text": "θ = sin⁻¹(π²R/gT²)^½"}, {"id": "c", "text": "θ = sin⁻¹(2gT²/π²R)^½"}, {"id": "d", "text": "θ = cos⁻¹(gT²/π²R)^½"}]'::jsonb, 'c', 'v = 2πR/T; v² sin²θ/2g = 4R gives sin²θ = 2gT²/(π²R).', 'The speed is v = 2πR/T. Setting H = v² sin²θ/(2g) = 4R gives sin²θ = 8gR/v² = 8gRT²/(4π²R²) = 2gT²/(π²R). So θ = sin⁻¹(2gT²/π²R)^½.', '{"a": "Uses cos and inverts the ratio.", "b": "Inverts the ratio and drops the factor 2.", "d": "Uses cos and drops the factor 2."}'::jsonb, 'Maximum height of a projectile: H = u² sin²θ/(2g).', 'med', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('40d8b893-3c1a-5201-8497-3d23c36e0ba8', 'neet_ug', 'Physics', 'Motion in a Plane', 'A car starts from rest and accelerates at 5 m/s². At t = 4 s, a ball is dropped out of a window by a person sitting in the car. What is the velocity and acceleration of the ball at t = 6 s ?', '[{"id": "a", "text": "20 m/s, 0"}, {"id": "b", "text": "20√2 m/s, 0"}, {"id": "c", "text": "20√2 m/s, 10 m/s²"}, {"id": "d", "text": "20 m/s, 5 m/s²"}]'::jsonb, 'c', 'The ball keeps 20 m/s horizontally, gains 20 m/s vertically in 2 s, and has acceleration g.', 'At t = 4 s the car''s speed is 5 × 4 = 20 m/s, which the ball keeps horizontally after release. In the next 2 s it gains a vertical speed of g × 2 = 20 m/s. So v = √(20² + 20²) = 20√2 m/s. Once released, the only acceleration is g = 10 m/s² downward.', '{"a": "Ignores the vertical velocity and gravity.", "b": "Ignores gravitational acceleration.", "d": "After release the ball no longer shares the car''s acceleration."}'::jsonb, 'Once released, a body keeps the velocity of the carrier but its acceleration becomes only g.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('9d7f150c-bdb6-54f5-8d8c-c81ab73e1dcc', 'neet_ug', 'Physics', 'Work, Energy and Power', 'A ball of mass 0.15 kg is dropped from a height 10 m, strikes the ground and rebounds to the same height. The magnitude of impulse imparted to the ball is (g = 10 m/s²) nearly:', '[{"id": "a", "text": "4.2 kg m/s"}, {"id": "b", "text": "2.1 kg m/s"}, {"id": "c", "text": "1.4 kg m/s"}, {"id": "d", "text": "0 kg m/s"}]'::jsonb, 'a', 'v = √(2gh) = 10√2 m/s, and J = 2mv ≈ 4.2 kg m/s.', 'The impact speed is √(2 × 10 × 10) = 14.14 m/s. It rebounds to the same height, so it leaves upward at 14.14 m/s. Impulse = Δp = m(v + v) = 0.15 × 28.28 ≈ 4.2 kg m/s.', '{"b": "Takes only mv and ignores the reversal of direction.", "c": "Arithmetic error.", "d": "Confuses equal speeds with zero change in momentum."}'::jsonb, 'Impulse equals the change in momentum, a vector; reversing the velocity doubles it.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('6fc46737-e806-5a6d-ac44-fee6c8b53a81', 'neet_ug', 'Physics', 'System of Particles and Rotational Motion', 'A uniform rod of length 200 cm and mass 500 g is balanced on a wedge placed at 40 cm mark. A mass of 2 kg is suspended from the rod at 20 cm and another unknown mass ''m'' is suspended from the rod at 160 cm mark as shown in the figure. Find the value of ''m'' such that the rod is in equilibrium. (g = 10 m/s²)', '[{"id": "a", "text": "1/3 kg"}, {"id": "b", "text": "1/6 kg"}, {"id": "c", "text": "1/12 kg"}, {"id": "d", "text": "1/2 kg"}]'::jsonb, 'c', 'Torques about the 40 cm mark: 2 × 20 = 0.5 × 60 + m × 120, so m = 1/12 kg.', 'Take torques about the wedge at 40 cm. The 2 kg mass is 20 cm to the left. The rod''s weight acts at 100 cm, 60 cm to the right, and m hangs 120 cm to the right. Balance gives 2 × 20 = 0.5 × 60 + 120m, so 40 = 30 + 120m and m = 1/12 kg.', '{"a": "Ignores the rod''s own weight or misreads the lever arms.", "b": "Lever-arm error.", "d": "Lever-arm error."}'::jsonb, 'For rotational equilibrium, the net torque about any point is zero; a uniform rod''s weight acts at its centre.', 'med', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', '/pyq/ug/2021/2539.webp'),
('b2831686-ac28-586f-8341-840e7244f534', 'neet_ug', 'Physics', 'System of Particles and Rotational Motion', 'From a circular ring of mass ''M'' and radius ''R'' an arc corresponding to a 90° sector is removed. The moment of inertia of the remaining part of the ring about an axis passing through the centre of the ring and perpendicular to the plane of the ring is ''K'' times ''MR²''. Then the value of ''K'' is:', '[{"id": "a", "text": "7/8"}, {"id": "b", "text": "1/4"}, {"id": "c", "text": "1/8"}, {"id": "d", "text": "3/4"}]'::jsonb, 'd', 'Three-quarters of the mass remains, all at distance R, so I = (3/4)MR².', 'Every element of the ring is at distance R from the axis, so I = (mass remaining)R². Removing a 90° arc removes a quarter of the mass and leaves 3M/4. So I = (3/4)MR² and K = 3/4.', '{"a": "Not a sector fraction of the ring.", "b": "This is the moment of inertia of the removed arc.", "c": "Halves the removed part."}'::jsonb, 'The moment of inertia of any arc of a ring about its central axis is (arc mass) × R².', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('2fd8837c-4cc8-5d0f-82d6-2506b232fe1f', 'neet_ug', 'Physics', 'Gravitation', 'A particle of mass ''m'' is projected with a velocity v = kV_e (k < 1) from the surface of the earth.
The maximum height above the surface reached by the particle is:', '[{"id": "a", "text": "R(k/(1+k))²"}, {"id": "b", "text": "R²k/(1+k)"}, {"id": "c", "text": "Rk²/(1−k²)"}, {"id": "d", "text": "R(k/(1−k))²"}]'::jsonb, 'c', 'Energy conservation with V_e² = 2GM/R gives h = Rk²/(1 − k²).', 'Energy conservation gives (1/2)mk²(2GM/R) − GMm/R = −GMm/(R + h). Then (GM/R)(k² − 1) = −GM/(R + h), so R + h = R/(1 − k²) and h = Rk²/(1 − k²).', '{"a": "Wrong algebra.", "b": "Dimensionally wrong.", "d": "Wrong algebra."}'::jsonb, 'Escape speed V_e = √(2GM/R) = √(2gR) ≈ 11.2 km/s for Earth.', 'med', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('38e33f6f-34ab-574e-b367-d2921ed4d0f0', 'neet_ug', 'Physics', 'Electrostatic Potential and Capacitance', 'Twenty seven drops of same size are charged at 220 V each. They combine to form a bigger drop. Calculate the potential of the bigger drop.', '[{"id": "a", "text": "1320 V"}, {"id": "b", "text": "1520 V"}, {"id": "c", "text": "1980 V"}, {"id": "d", "text": "660 V"}]'::jsonb, 'c', 'V_big = n^(2/3) V = 9 × 220 = 1980 V.', 'Volume is conserved, so R = 27^(1/3) r = 3r, and the charge is 27q. V = k(27q)/(3r) = 9 × kq/r = 9 × 220 = 1980 V.', '{"a": "Uses factor 6.", "b": "Not a power of 27.", "d": "Uses n^(1/3) = 3 instead of n^(2/3)."}'::jsonb, 'When n identical drops merge: V → n^(2/3)V, Q → nQ, C → n^(1/3)C.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('8852d136-b316-5456-92e4-d51e9254fe90', 'neet_ug', 'Physics', 'Current Electricity', 'Three resistors having resistances r₁, r₂ and r₃ are connected as shown in the given circuit. The ratio i₃/i₁ of currents in terms of resistances used in the circuit is:', '[{"id": "a", "text": "r₂/(r₂ + r₃)"}, {"id": "b", "text": "r₁/(r₁ + r₂)"}, {"id": "c", "text": "r₂/(r₁ + r₃)"}, {"id": "d", "text": "r₁/(r₂ + r₃)"}]'::jsonb, 'a', 'Current divider: i₃ = i₁ r₂/(r₂ + r₃).', 'i₁ splits between r₂ and r₃ in parallel. These share the same voltage, so i₂r₂ = i₃r₃ with i₂ + i₃ = i₁. Solving gives i₃ = i₁ r₂/(r₂ + r₃).', '{"b": "r₁ carries the full i₁ and plays no part in the division.", "c": "Mixes the series resistor into the divider.", "d": "Mixes the series resistor into the divider."}'::jsonb, 'In a two-branch parallel split, each branch current is proportional to the other branch''s resistance.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', '/pyq/ug/2021/2543.webp'),
('d3d3f394-9695-5d1e-a209-c06c3aa7739f', 'neet_ug', 'Physics', 'Moving Charges and Magnetism', 'In the product
F = q(v × B)
= qv × (Bî + Bĵ + B₀k̂)
For q = 1 and v = 2î + 4ĵ + 6k̂ and
F = 4î − 20ĵ + 12k̂
What will be the complete expression for B ?', '[{"id": "a", "text": "−6î − 6ĵ − 8k̂"}, {"id": "b", "text": "8î + 8ĵ − 6k̂"}, {"id": "c", "text": "6î + 6ĵ − 8k̂"}, {"id": "d", "text": "−8î − 8ĵ − 6k̂"}]'::jsonb, 'a', 'Comparing v × B components gives B = −6 and B₀ = −8.', 'v × B = (4B₀ − 6B)î + (6B − 2B₀)ĵ + (2B − 4B)k̂. The k̂ component gives −2B = 12, so B = −6. The î component gives 4B₀ + 36 = 4, so B₀ = −8. Check the ĵ component: −36 + 16 = −20 ✓. So B = −6î − 6ĵ − 8k̂.', '{"b": "The î and ĵ components of B must be equal and give the stated F; this one does not.", "c": "Has the wrong signs on the î and ĵ components.", "d": "Swaps B and B₀."}'::jsonb, 'The magnetic force qv × B is always perpendicular to both v and B, so it does no work.', 'med', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('cc656465-72c4-583e-a6ab-70b42f95e986', 'neet_ug', 'Physics', 'Moving Charges and Magnetism', 'A uniform conducting wire of length 12 a and resistance ''R'' is wound up as a current carrying coil in the shape of,
i. an equilateral triangle of side ''a''.
ii. a square of side ''a''.
The magnetic dipole moments of the coil in each case respectively are:', '[{"id": "a", "text": "3 Ia² and Ia²"}, {"id": "b", "text": "3 Ia² and 4 Ia²"}, {"id": "c", "text": "4 Ia² and 3 Ia²"}, {"id": "d", "text": "√3 Ia² and 3 Ia²"}]'::jsonb, 'd', 'The triangle has 4 turns of area (√3/4)a², giving √3 Ia²; the square has 3 turns of area a², giving 3Ia².', 'A triangle of side a uses 3a of wire, so 12a makes 4 turns. Then m = 4 × I × (√3/4)a² = √3 Ia². A square uses 4a per turn, giving 3 turns, so m = 3Ia².', '{"a": "Wrong number of turns or area.", "b": "Wrong number of turns or area.", "c": "Uses the number of turns as the moment and ignores the triangle''s area."}'::jsonb, 'Magnetic moment of a coil: m = NIA, directed along the area normal (right-hand rule).', 'med', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('0fd9ac05-e883-530a-8882-d910c9a3b296', 'neet_ug', 'Physics', 'Electromagnetic Induction', 'Two conducting circular loops of radii R₁ and R₂ are placed in the same plane with their centres coinciding. If R₁ >> R₂, the mutual inductance M between them will be directly proportional to:', '[{"id": "a", "text": "R₂/R₁"}, {"id": "b", "text": "R₁²/R₂"}, {"id": "c", "text": "R₂²/R₁"}, {"id": "d", "text": "R₁/R₂"}]'::jsonb, 'c', 'M = μ₀πR₂²/(2R₁).', 'Current I in the large loop gives a nearly uniform field μ₀I/(2R₁) over the small loop. The flux through the small loop is μ₀IπR₂²/(2R₁). So M = μ₀πR₂²/(2R₁) ∝ R₂²/R₁.', '{"a": "Misses the area dependence.", "b": "Inverts the roles of the two loops.", "d": "Inverted ratio."}'::jsonb, 'Mutual inductance is the same whichever coil carries the current (M₁₂ = M₂₁).', 'med', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('7dda6436-228d-56c2-8186-145b6bf0da04', 'neet_ug', 'Physics', 'Alternating Current', 'A step down transformer connected to an ac mains supply of 220 V is made to operate at 11 V, 44 W lamp. Ignoring power losses in the transformer, what is the current in the primary circuit?', '[{"id": "a", "text": "0.4 A"}, {"id": "b", "text": "2 A"}, {"id": "c", "text": "4 A"}, {"id": "d", "text": "0.2 A"}]'::jsonb, 'd', 'For an ideal transformer, I_p = P/V_p = 44/220 = 0.2 A.', 'With no losses, input power equals output power = 44 W. So I_p = 44/220 = 0.2 A. The secondary carries 44/11 = 4 A.', '{"a": "Double the correct value.", "b": "Arithmetic error.", "c": "This is the secondary current."}'::jsonb, 'Ideal transformer: V_sI_s = V_pI_p and V_s/V_p = N_s/N_p.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('3b062bcb-6f62-530f-a5be-c3c9235e1209', 'neet_ug', 'Physics', 'Alternating Current', 'A series LCR circuit containing 5.0 H inductor, 80 μF capacitor and 40 Ω resistor is connected to 230 V variable frequency ac source. The angular frequencies of the source at which power transferred to the circuit is half the power at the resonant angular frequency are likely to be:', '[{"id": "a", "text": "50 rad/s and 25 rad/s"}, {"id": "b", "text": "46 rad/s and 54 rad/s"}, {"id": "c", "text": "42 rad/s and 58 rad/s"}, {"id": "d", "text": "25 rad/s and 75 rad/s"}]'::jsonb, 'b', 'ω₀ = 1/√(LC) = 50 rad/s; half-power points at ω₀ ± R/2L = 50 ± 4.', 'ω₀ = 1/√(5 × 80 × 10⁻⁶) = 1/(2 × 10⁻²) = 50 rad/s. The half-power points lie at ω₀ ± R/(2L) = 50 ± 40/10 = 50 ± 4, which is 46 and 54 rad/s.', '{"a": "Not symmetric about ω₀.", "c": "Uses R/L instead of R/(2L).", "d": "Far too wide a band."}'::jsonb, 'Bandwidth Δω = R/L; quality factor Q = ω₀L/R.', 'med', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL),
('cf286712-25f6-584f-9d53-d4946358a319', 'neet_ug', 'Botany', 'Organisms and Populations', 'Assertion (A): A person goes to high altitude and experiences ‘altitude sickness’ with symptoms like breathing difficulty and heart palpitations.
Reason (R): Due to low atmospheric pressure at high altitude, the body does not get sufficient oxygen.
In the light of the above statements, choose the correct answer from the options given below.', '[{"id": "a", "text": "Both (A) and (R) are true but (R) is not the correct explanation of (A)"}, {"id": "b", "text": "(A) is true but (R) is false"}, {"id": "c", "text": "(A) is false but (R) is true"}, {"id": "d", "text": "Both (A) and (R) are true and (R) is the correct explanation of (A)"}]'::jsonb, 'd', 'Low atmospheric pressure at altitude lowers oxygen availability, causing altitude sickness.', 'At high altitude the low atmospheric pressure means less oxygen reaches the body, producing nausea, fatigue and heart palpitations. The body later acclimatises by increasing RBC production, lowering haemoglobin''s binding affinity and raising breathing rate. So R correctly explains A.', '{"a": "R does explain A.", "b": "R is true.", "c": "A is true."}'::jsonb, 'Acclimatisation: more RBCs, lower Hb O₂ affinity, faster breathing.', 'easy', true, 2021, NULL, 'NEET UG 2021 (NTA) · answer verified by UG Prep', NULL)
ON CONFLICT (id) DO NOTHING;
